insert into public.works (museum_id, language, id, position, title, category, subtitle, artist, facts, object_url, image, guide)
select museum_id, language, id, position, title, category, subtitle, artist, facts, object_url, image, guide
from jsonb_populate_recordset(null::public.works, $seed$[{"museum_id":"cleveland","language":"en","id":"cma-1916-1043","position":0,"title":"Dancers","category":"Drawings","subtitle":null,"artist":"Edgar Degas (French, 1834–1917)","facts":[{"label":"Date","value":"c. 1896"},{"label":"Medium","value":"pastel with charcoal on tracing paper mounted on paper and backed with gray board"},{"label":"Accession","value":"1916.1043"}],"object_url":"https://clevelandart.org/art/1916.1043","image":{"src":"/images/cleveland/cma-1916-1043.jpg","sourceUrl":"https://clevelandart.org/art/1916.1043","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"Degas depicted the ballet in more than 1,000 paintings, prints, pastels, and sculptures. He preferred private, offstage moments to glamorous curtain calls or artfully constructed compositions. Here, three dancers stretch together in the wings, unaware of the viewer’s presence. Powdery layers of yellow, orange, and pink pastel create a rough surface characteristic of Degas’s late work in the medium. He invented special techniques that allowed him to build layer upon layer of color with varying degrees of opacity and transparency. This pastel’s rich surface and intense, vibrating palette is the result of such innovative methods."}},{"museum_id":"cleveland","language":"en","id":"cma-1920-379","position":1,"title":"After the Bath","category":"Drawings","subtitle":null,"artist":"Mary Cassatt (American, 1844–1926)","facts":[{"label":"Date","value":"1901"},{"label":"Medium","value":"pastel"},{"label":"Accession","value":"1920.379"}],"object_url":"https://clevelandart.org/art/1920.379","image":{"src":"/images/cleveland/cma-1920-379.jpg","sourceUrl":"https://clevelandart.org/art/1920.379","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"Mary Cassatt began using pastel in the 1870s and continued to experiment with the medium throughout her career. This drawing depicts a mother and child, one of the artist's preferred subjects. Cassatt typically used the technique seen here, in which she finished her sitters' faces with a high degree of detail but rendered the rest of the composition in a much looser and sketchier style."}},{"museum_id":"cleveland","language":"en","id":"cma-1925-1409","position":2,"title":"Monsieur Boileau at the Café","category":"Drawings","subtitle":null,"artist":"Henri de Toulouse-Lautrec (French, 1864–1901)","facts":[{"label":"Date","value":"1893"},{"label":"Medium","value":"oil and tempera with charcoal on millboard"},{"label":"Accession","value":"1925.1409"}],"object_url":"https://clevelandart.org/art/1925.1409","image":{"src":"/images/cleveland/cma-1925-1409.jpg","sourceUrl":"https://clevelandart.org/art/1925.1409","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"Cleveland’s 1925 purchase of this work by Henri de Toulouse-Lautrec marked the first acquisition of one of the artist’s drawings by a museum in the United States. Its subject, Monsieur Boileau, was a gossip columnist known to drink heavily at Le Mirliton, a nightclub. Here, saturated, acidic tones evoke the room’s gas lamps and thinned oil paint absorbs into its support, producing texture that complements the scene’s grittiness. In his own time, Toulouse-Lautrec was considered a portraitist for such depictions of friends and other inhabitants of his neighborhood. He preferred drawing for its immediacy, using it to record his sitters’ personalities through materials and formal choices."}},{"museum_id":"cleveland","language":"en","id":"cma-1926-25","position":3,"title":"Orpheus","category":"Drawings","subtitle":null,"artist":"Odilon Redon (French, 1840–1916)","facts":[{"label":"Date","value":"c. 1903–10"},{"label":"Medium","value":"pastel on brown paper"},{"label":"Accession","value":"1926.25"}],"object_url":"https://clevelandart.org/art/1926.25","image":{"src":"/images/cleveland/cma-1926-25.jpg","sourceUrl":"https://clevelandart.org/art/1926.25","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"Drawn in vivid layers of pastel crayon, this work depicts the head of the poet and musician Orpheus. The story of the god of music, whose music carried on after his death through his lyre and head, fascinated Redon, who related to Orpheus's dedication to his art. The subject also aligned with Redon's broader interest in dreams and spirituality around this time and he represented Orpheus several times throughout his career, in various media. Here, the god's head floats as if in stasis while Mount Parnassus—the home of Apollo and the Muses—soars from behind."}},{"museum_id":"cleveland","language":"en","id":"cma-1938-56","position":4,"title":"Smelting Works at Denver","category":"Drawings","subtitle":null,"artist":"Thomas Moran (American, born England, 1837–1926)","facts":[{"label":"Date","value":"1892"},{"label":"Medium","value":"watercolor and gouache"},{"label":"Accession","value":"1938.56"}],"object_url":"https://clevelandart.org/art/1938.56","image":{"src":"/images/cleveland/cma-1938-56.jpg","sourceUrl":"https://clevelandart.org/art/1938.56","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"For today's viewers of Thomas Moran’s watercolor, the sight of factory smoke pouring into pristine mountain air might prophesy environmental ruin. Yet within the context of America’s western expansion, the imagery of factories was more ambiguous. Some in Moran's time regarded the factories as a force of destruction, while others interpreted them as symbols of progress. Moran himself viewed Denver’s budding industry with enthusiasm, writing positively to his wife about the city’s growth since he first visited while part of a government survey in 1873. Two decades later, when Moran returned to Denver to paint advertisements for the Santa Fe Railroad, smelting—the extraction of metal from heated rock—had transformed the city into an industrial hub. Although the brooding tone of this watercolor is unlike the artist’s bright, misty-eyed paintings of Edenic splendor, his depiction of the west’s emerging industrial landscape reinforces the same myth of manifest destiny—the belief that settler conquest of Native American lands was inevitable and justified—by illustrating the land’s richness in natural resources. Like the English Romantic painter J. M. W. Turner, whose style he emulated, Moran was primarily interested in the pictorial possibilities of industry. In this impressionistic study, Moran manipulates gray wash and white gouache to capture the vaporous quality of smoke and clouds as the two substances, industrial and natural, dissipate into the yellow atmosphere."}},{"museum_id":"cleveland","language":"en","id":"cma-1938-387","position":5,"title":"A Young Woman Buying a Pink from a Young Man","category":"Drawings","subtitle":null,"artist":"Giovanni Battista Piazzetta (Italian, 1682–1754)","facts":[{"label":"Date","value":"c. 1740"},{"label":"Medium","value":"black crayon (wetted and rubbed) heightened with white chalk on faded blue paper"},{"label":"Accession","value":"1938.387"}],"object_url":"https://clevelandart.org/art/1938.387","image":{"src":"/images/cleveland/cma-1938-387.jpg","sourceUrl":"https://clevelandart.org/art/1938.387","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"Giovanni Battista Piazzetta was celebrated for his finished drawings of saints, portraits, and teste di carattere (character heads). Cleveland’s sheet belongs to the latter genre, which describes portraits embellished with props to suggest a character type or types. Here, Piazzetta united three independent studies of individuals into a single scene, in which a young woman appears to purchase a pink—a type of flower related to the carnation—from a boy with a second young woman looking on.The image bristles with tantalizing narrative potential, but it is left to the viewer to interpret the scene as they wish. Drawings of this size and quality of finish were displayed on walls like paintings, rather than stored in portfolios, with the unfortunate consequence that the Venetian blue paper often faded to a grayish-tan as here. However, the virtuosity of Piazzetta’s technique endures on this sheet. His method of modeling—wetting and rubbing his black crayon rather than hatching—produces the density of tone and velvety shadow. Textural details are supplied by white chalk, evoking the silky weave of the boy’s shirt and the hard substance of the figures’ fingernails. Piazzetta's drawings were in high demand among affluent foreign visitors and helped to supplement his income."}},{"museum_id":"cleveland","language":"en","id":"cma-1940-465","position":6,"title":"Study for the Nude Youth over the Prophet Daniel (recto); Figure Studies for the Sistine Ceiling (verso)","category":"Drawings","subtitle":null,"artist":"Michelangelo Buonarroti (Italian, 1475–1564)","facts":[{"label":"Date","value":"1510–11"},{"label":"Medium","value":"red chalk over black chalk or charcoal"},{"label":"Accession","value":"1940.465"}],"object_url":"https://clevelandart.org/art/1940.465","image":{"src":"/images/cleveland/cma-1940-465.jpg","sourceUrl":"https://clevelandart.org/art/1940.465","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"Universally considered one of the greatest artists of the Italian Renaissance, Michelangelo devoted four years to painting the vast ceiling fresco in the Sistine Chapel. This preparatory study portrays one of the 20 athletic male nudes, known as ignudi, who serve as supporting figures at each corner of the Old Testament scenes painted down the center of the ceiling. Michelangelo worked out the positioning of the ignudi in red chalk drawings before beginning to paint each section of wet plaster. The energy and monumentality of the figure in red chalk, whose body extends beyond the sheet, suggests the heroic athleticism of Michelangelo’s sculpture."}},{"museum_id":"cleveland","language":"en","id":"cma-1943-657","position":7,"title":"Invocation to Love","category":"Drawings","subtitle":null,"artist":"Jean-Honoré Fragonard (French, 1732–1806)","facts":[{"label":"Date","value":"c. 1781"},{"label":"Medium","value":"Brush and brown wash with graphite squaring lines and underdrawing on cream laid paper"},{"label":"Accession","value":"1943.657"}],"object_url":"https://clevelandart.org/art/1943.657","image":{"src":"/images/cleveland/cma-1943-657.jpg","sourceUrl":"https://clevelandart.org/art/1943.657","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"Fragonard used gardens as the setting for love and courtship in some of his most important works. One such scene, this drawing depicts a woman pleading for help from a statue of Eros, the god of love. He wears a blindfold, suggesting an uncertain outcome for the woman, as does a Cupid who indifferently leans on an orb nearby. Like other artists in 18th-century France, Fragonard was deeply influenced by historic imagery of the Garden of Love—a pastoral and idyllic contained landscape. He revisited the specific image seen here multiple times, in two oil paintings (Musée du Louvre and private collection, New York) and another drawing (Princeton University Art Museum)."}},{"museum_id":"cleveland","language":"en","id":"cma-1946-217","position":8,"title":"Dead Blue Roller","category":"Drawings","subtitle":null,"artist":"Hans Hoffmann (German, 1545/50–1591/92) · Albrecht Dürer (German, 1471–1528)","facts":[{"label":"Date","value":"1583"},{"label":"Medium","value":"watercolor and gouache with touches of gold"},{"label":"Accession","value":"1946.217"}],"object_url":"https://clevelandart.org/art/1946.217","image":{"src":"/images/cleveland/cma-1946-217.jpg","sourceUrl":"https://clevelandart.org/art/1946.217","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"Half a century after the death of the German Renaissance artist Albrecht Dürer, his work continued to inspire artists and collectors. Hans Hoffmann was well known for his copies of Dürer’s nature studies, and in 1583 he faithfully copied Dürer’s celebrated drawing of a dead blue roller of 1512 in this exquisite watercolor. A network of very fine brushstrokes imitates the individual plumes of the bird’s underside while simultaneously suggesting an overall soft, downy texture. Several other copies of Dürer's composition exist, including one by Hoffmann in London. Both the London sheet and this sheet were signed with Hoffman’s prominent monogram and dated, indicating that he could not have intended them to pass as originals by the older master. Likely, he meant the drawing as an homage to the greatest German artist of the 1500s; his endeavor may have been sponsored by the Nuremberg-based Imhoff family, who owned Dürer's blue roller around the time this drawing was made."}},{"museum_id":"cleveland","language":"en","id":"cma-1949-439","position":9,"title":"Head of a Tahitian Woman","category":"Drawings","subtitle":null,"artist":"Paul Gauguin (French, 1848–1903)","facts":[{"label":"Date","value":"1891"},{"label":"Medium","value":"graphite with stumping and graphite wash on parchment"},{"label":"Accession","value":"1949.439"}],"object_url":"https://clevelandart.org/art/1949.439","image":{"src":"/images/cleveland/cma-1949-439.jpg","sourceUrl":"https://clevelandart.org/art/1949.439","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"This drawing belongs to a group of highly finished portrait drawings of Tahitians made by Paul Gauguin shortly after his arrival in the South Seas. While getting used to this new place, Gauguin initially avoided painting, preferring first to familiarize himself with the landscape and people through observation and drawing. The meticulous quality of this graphite study suggests that it was made from life. The woman’s noble face and enigmatic expression allude to the spirituality and melancholy that Gauguin sought to conjure in his Polynesian work."}},{"museum_id":"cleveland","language":"en","id":"cma-1949-544","position":10,"title":"Church Bells Ringing, Rainy Winter Night","category":"Drawings","subtitle":null,"artist":"Charles Burchfield (American, 1893–1967)","facts":[{"label":"Date","value":"December 1917"},{"label":"Medium","value":"watercolor and gouache over graphite on wove paper"},{"label":"Accession","value":"1949.544"}],"object_url":"https://clevelandart.org/art/1949.544","image":{"src":"/images/cleveland/cma-1949-544.jpg","sourceUrl":"https://clevelandart.org/art/1949.544","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"Burchfield considered this drawing among the greatest accomplishments of his “golden year.” This period followed a time of self-doubt and uncertainty: after graduating from the Cleveland School of Art, Burchfield enrolled in the National Academy of Design in New York City, but dropped out after one day, returning to Salem to work an office job. He painted inexhaustibly during his breaks and at night, depicting Salem and its environs in an increasingly abstract style. Church Bells Ringing, Rainy Winter Night shows the spire of Salem’s Baptist church rising up between two houses. Burchfield hoped to express his powerful childhood fear of the bell’s ominous ring—which he described as “a dull roar . . . dying slowly & with a growl.” Hearing it on stormy winter nights, he huddled in his bed and calmed himself by thinking of Christmas, a practice suggested by the tree visible through a window in the drawing. Burchfield carefully refined the composition throughout the sketches seen in this gallery. The drawing’s mood is conveyed through gray tones and the buildings’ hulking forms. Burchfield also created a complex language of symbols entitled “Conventions for Abstract Thoughts,” that recurred throughout his work and represented universal emotions. The hooked forms surrounding the tower stood for “Fear,” for example, and the shapes of the houses’ doors and windows symbolize “Morbidness” and “Evil.” Developed fully in this drawing, these symbols dominated Burchfield’s work during the remaining several years he spent in Ohio."}},{"museum_id":"cleveland","language":"en","id":"cma-1951-430","position":11,"title":"Sheet of Studies and Sketches","category":"Drawings","subtitle":null,"artist":"Edgar Degas (French, 1834–1917)","facts":[{"label":"Date","value":"1858"},{"label":"Medium","value":"graphite, pen and dark brown ink, and watercolor on thick ivory wove paper"},{"label":"Accession","value":"1951.430"}],"object_url":"https://clevelandart.org/art/1951.430","image":{"src":"/images/cleveland/cma-1951-430.jpg","sourceUrl":"https://clevelandart.org/art/1951.430","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"Degas traveled to Florence, Italy, in July 1858, where he made this sheet of studies. The featured imagery is fragmented and dissociated, suggesting the young artist's engagement with art of the past. The refined female head drawn at center in graphite was copied from a drawing then attributed to Leonardo da Vinci in the Uffizi Gallery's collection. Other sketches record Degas's responses to Florentine sculpture. At upper right, he sketched an informal portrait of his cousin Giulia Bellelli, probably from life."}},{"museum_id":"cleveland","language":"en","id":"cma-1954-128","position":12,"title":"Boy with Anchor","category":"Drawings","subtitle":null,"artist":"Winslow Homer (American, 1836–1910)","facts":[{"label":"Date","value":"1873"},{"label":"Medium","value":"Watercolor and graphite on paper"},{"label":"Accession","value":"1954.128"}],"object_url":"https://clevelandart.org/art/1954.128","image":{"src":"/images/cleveland/cma-1954-128.jpg","sourceUrl":"https://clevelandart.org/art/1954.128","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"In this work from a series of watercolors produced in Gloucester, MA, in the summer of 1873 Winslow Homer evokes the fraught nature of the local fishing industry by focusing not on the perilous work of adults, but rather the children they leave behind. In Boy with Anchor, the massive anchor pointing toward the sea foreshadows the weight of the boy’s maritime destiny. The work is an early example of Homer's talent for evoking atmospheric effects and his interest in technical variety. Presumably working outdoors, Homer layered fluent washes of blue, gray, and brown transparent watercolor over his graphite underdrawing to flesh out the beach and sky. He built up the hot, pebble-studded surface of the beach by using dense gouache to draw textural detail and created the broken cloud pattern in the sky by lightly blotting his wet blue wash. The picture’s formal tensions between warm and cool colors, outline and wash, and transparency and opacity mirror the emotional tension of the scene."}},{"museum_id":"cleveland","language":"en","id":"cma-1956-718","position":13,"title":"Claire Campbell","category":"Drawings","subtitle":null,"artist":"Édouard Manet (French, 1832–1883)","facts":[{"label":"Date","value":"1876"},{"label":"Medium","value":"Pastel with oil on fine-weave canvas"},{"label":"Accession","value":"1956.718"}],"object_url":"https://clevelandart.org/art/1956.718","image":{"src":"/images/cleveland/cma-1956-718.jpg","sourceUrl":"https://clevelandart.org/art/1956.718","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"During the late 1870s, Edouard Manet began to experience health problems that made it difficult for him to work in oil painting. Instead, he began to draw using pastel, a powdery medium that allowed him to render line and color with each stroke. This work is one of numerous portraits that Manet created around this time with the medium. It depicts Claire Campbell, a fashionable young British woman whose father published The Daily Telegraph, a British newspaper. Manet used the velvety texture of pastel to render the subject's skin and hair, limiting his palette to mostly neutral tones such as white, gray, and black."}},{"museum_id":"cleveland","language":"en","id":"cma-1957-498","position":14,"title":"Farmhouse on the Slope of a Hill","category":"Drawings","subtitle":null,"artist":"Fra Bartolommeo (Italian, 1472–1517)","facts":[{"label":"Date","value":"c. 1508"},{"label":"Medium","value":"pen and brown ink"},{"label":"Accession","value":"1957.498"}],"object_url":"https://clevelandart.org/art/1957.498","image":{"src":"/images/cleveland/cma-1957-498.jpg","sourceUrl":"https://clevelandart.org/art/1957.498","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"This is a significant early example of pure landscape drawing in Europe, as it is dedicated completely to the depiction of nature for its own sake, without suggestion of a biblical or historical narrative. The rapidity and regularity of strokes used for the evergreen and deciduous trees and the sweeping lines in the foreground suggest that the landscape in Farmhouse on the Slope of a Hill was made directly from nature. The sheet comes from an album of 41 landscape studies by Fra Bartolommeo assembled by an eighteenth-century collector and disbound for sale in the mid-20th century. A member of the Dominican Order, Fra Bartolomeo likely produced these drawings during his travels in and around Florence, often to Dominican establishments."}},{"museum_id":"cleveland","language":"en","id":"cma-1958-30","position":15,"title":"Landscape with Wheelbarrow","category":"Drawings","subtitle":null,"artist":"Vincent van Gogh (Dutch, 1853–1890)","facts":[{"label":"Date","value":"1883"},{"label":"Medium","value":"watercolor and opaque watercolor with black chalk on cream paper"},{"label":"Accession","value":"1958.30"}],"object_url":"https://clevelandart.org/art/1958.30","image":{"src":"/images/cleveland/cma-1958-30.jpg","sourceUrl":"https://clevelandart.org/art/1958.30","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"In September 1883 Van Gogh left the bustling Dutch city of The Hague in search of open countryside in which to paint. He moved to Drenthe, a village in northeastern Netherlands that was virtually untouched by the Industrial Revolution. He described the barren terrain as supremely beautiful and serene: \"What tranquility, what expanse, what calmness in this nature.\" With a limited palette of steely greens and cool blues, Van Gogh masterfully portrayed one of the region’s expanses of heath—\"a vast plane vanishing into infinity\"—illuminated by the lilac hues of the evening sky."}},{"museum_id":"cleveland","language":"en","id":"cma-1958-344","position":16,"title":"At the Concert Parisien","category":"Drawings","subtitle":null,"artist":"Georges Seurat (French, 1859–1891)","facts":[{"label":"Date","value":"1887–88"},{"label":"Medium","value":"conté crayon heightened with white chalk on cream handmade modern laid paper"},{"label":"Accession","value":"1958.344"}],"object_url":"https://clevelandart.org/art/1958.344","image":{"src":"/images/cleveland/cma-1958-344.jpg","sourceUrl":"https://clevelandart.org/art/1958.344","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"Café-concerts were popular places of entertainment for the middle classes in Paris during the late 1800s and usually featured singers or other forms of vaudeville entertainers. Georges Seurat created eight drawings depicting café-concerts, some showing known establishments. This drawing has an innovative viewpoint, in which we peer through the bowler hats of male viewers listening to a female singer on stage. Seurat typically used a black crayon manufactured by the Conté company, and its waxy quality allowed him to exploit the texture of paper to striking effect."}},{"museum_id":"cleveland","language":"en","id":"cma-1958-411","position":17,"title":"Saint Sebastian","category":"Drawings","subtitle":null,"artist":"Perugino (Italian, c. 1450/55–1523)","facts":[{"label":"Date","value":"c. 1493"},{"label":"Medium","value":"metalpoint"},{"label":"Accession","value":"1958.411"}],"object_url":"https://clevelandart.org/art/1958.411","image":{"src":"/images/cleveland/cma-1958-411.jpg","sourceUrl":"https://clevelandart.org/art/1958.411","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"The Florentine painter Perugino made drawings to record figural types and poses that could be repeated throughout his finished paintings. He used the elegant, graceful figure seen here, with its soft athletic body and upwardly turned gaze, in at least two paintings of the 3rd-century martyr Saint Sebastian (the related paintings are now in the collection of the Galleria degli Uffizi, and the Louvre). Sebastian was shot with arrows after being exposed as a Christian convert; he was particularly revered during the Renaissance as a protector against illness such as the plague. Portrayal of the saint required Perugino to express his knowledge of human anatomy, while evoking the gentle s-curve associated with classical sculpture. Drawn with metalpoint, a typical drawing medium in the 1400s, the reinforced lines along the contour of the figure indicate that it was probably used by the artist or by one of his many studio assistants to transfer the design to another sheet."}},{"museum_id":"cleveland","language":"en","id":"cma-1965-470","position":18,"title":"Arm of Eve","category":"Drawings","subtitle":null,"artist":"Albrecht Dürer (German, 1471–1528)","facts":[{"label":"Date","value":"1507"},{"label":"Medium","value":"point of brush and gray and black wash, brush and gray and black wash, heightened with white gouache"},{"label":"Accession","value":"1965.470"}],"object_url":"https://clevelandart.org/art/1965.470","image":{"src":"/images/cleveland/cma-1965-470.jpg","sourceUrl":"https://clevelandart.org/art/1965.470","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"Arm of Eve is the only surviving preparatory drawing for Dürer’s life-size panels of Adam and Eve in the Museo del Prado, Madrid. It is also one of the few surviving drawings by the artist made on Venetian blue paper, a support he began to use for his chiaroscuro studies while visiting Venice in the winter of 1506–7. With extraordinary economy of means, using only black and gray ink and a limited amount of wash and gouache for shading and heightening, Dürer suggested the grace and balance of the complete human form in this composition of a disembodied arm and hand. Such a study of a hand in ideal proportions cannot help but suggest the hand of the artist, a self-referential nod to his own abilities."}},{"museum_id":"cleveland","language":"en","id":"cma-1968-66","position":19,"title":"Madonna Nursing the Christ Child","category":"Drawings","subtitle":null,"artist":"Bartolomé Esteban Murillo (Spanish, 1617–1682)","facts":[{"label":"Date","value":"c. 1670–72"},{"label":"Medium","value":"pen and brown ink and brush and brown wash over red and black chalk, with traces of white; framing lines in pen and brown ink"},{"label":"Accession","value":"1968.66"}],"object_url":"https://clevelandart.org/art/1968.66","image":{"src":"/images/cleveland/cma-1968-66.jpg","sourceUrl":"https://clevelandart.org/art/1968.66","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"One of the finest of the rare drawings by Murillo, this sheet is a study for Virgin and Child, commissioned for the family chapel of the Marques de Santiago in Madrid and now at the Metropolitan Museum of Art, New York. Prized today for their dynamism, Murillo’s drawings served the practical purpose of working out the positions of the figures. Here, the artist suggested the tender bond between mother and child with the poignant connection of their gazes. His animated line and zigzag hatching create the feeling of incessant motion while the addition of ink wash creates deep shadows across the forms."}},{"museum_id":"cleveland","language":"en","id":"cma-1934-373","position":20,"title":"Horse Stable","category":"Japanese Art","subtitle":null,"artist":null,"facts":[{"label":"Date","value":"early 1500s"},{"label":"Medium","value":"Pair of six-panel folding screens; ink, color, and gold on paper"},{"label":"Culture","value":"Japan, Muromachi period (1392–1573)"},{"label":"Accession","value":"1934.373"}],"object_url":"https://clevelandart.org/art/1934.373","image":{"src":"/images/cleveland/cma-1934-373.jpg","sourceUrl":"https://clevelandart.org/art/1934.373","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"Prized horses in stables may be the main theme of this pair of screens, but a lot of action is happening on the verandas. Falconry is the focus of one of the screens, while in the other, people challenge one another at two different boardgames, go and shōgi. A lively atmosphere develops in the interplay of the dynamic horses, the birds of prey, and the strategic games."}},{"museum_id":"cleveland","language":"en","id":"cma-1938-422","position":21,"title":"Medicine Master Buddha and the Twelve Divine Generals","category":"Japanese Art","subtitle":null,"artist":null,"facts":[{"label":"Date","value":"1200s"},{"label":"Medium","value":"Hanging scroll painting; ink, color, gold, and silver on silk"},{"label":"Culture","value":"Japan, Kamakura period (1185–1333)"},{"label":"Accession","value":"1938.422"}],"object_url":"https://clevelandart.org/art/1938.422","image":{"src":"/images/cleveland/cma-1938-422.jpg","sourceUrl":"https://clevelandart.org/art/1938.422","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"From the 700s, people in Japan began praying to the Medicine Master Buddha (Yakushi Nyorai) for longevity. Yakushi is at the center of this image, flanked by the bodhisattvas of the sun and moon, Nikkō and Gakkō. The Twelve Divine Generals, a group of protective deities, surround him. Yakushi sits in a meditative pose with his right hand in a gesture bestowing fearlessness while his left hand holds a medicine jar. In the upper part of the painting, rectangles simulating decorative paper inscription slips contain excerpts from a sacred text about Yakushi, in which he asks that sick people who speak his name should become well and that all who hear his name might have their purity restored."}},{"museum_id":"cleveland","language":"en","id":"cma-1948-128","position":22,"title":"Birds and Flowers","category":"Japanese Art","subtitle":null,"artist":"Kano Mitsunobu (Japanese, 1565–1608) · Kano Shōei (Japanese, 1519–1592)","facts":[{"label":"Date","value":"late 1500s"},{"label":"Medium","value":"Pair of six-panel folding screens; ink, color, and gold on paper"},{"label":"Accession","value":"1948.128"}],"object_url":"https://clevelandart.org/art/1948.128","image":{"src":"/images/cleveland/cma-1948-128.jpg","sourceUrl":"https://clevelandart.org/art/1948.128","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"The landscape depicted in this pair of screens follows a seasonal progression from right to left, starting with the blossoming plum of early spring and ending with late autumn peonies. A variety of smaller birds are positioned throughout the scene, and a trio of swimming ducks is bracketed by early summer irises and early autumn bellflowers at the center. While some raptors (birds of prey) terrorize a pheasant and an egret (a waterfowl) to the right, a peacock and peahen converse to the left. Hawks are associated with military prowess, while the peafowl suggest cultural prestige."}},{"museum_id":"cleveland","language":"en","id":"cma-1949-158","position":23,"title":"Gigaku Mask of Young Persian Boy (Taikōji)","category":"Japanese Art","subtitle":null,"artist":null,"facts":[{"label":"Date","value":"710–94"},{"label":"Medium","value":"paulownia wood, lacquered and painted"},{"label":"Culture","value":"Japan, Nara period (710–94)"},{"label":"Accession","value":"1949.158"}],"object_url":"https://clevelandart.org/art/1949.158","image":{"src":"/images/cleveland/cma-1949-158.jpg","sourceUrl":"https://clevelandart.org/art/1949.158","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"This mask is for the role of the son of an old Persian widower in gigaku, a theatrical dance repertoire imported to Japan from continental Asia during the seventh century. The old man and his sons mime prayers to the Buddha. While the mask would cover the entire head of the actor, there are openings for the eyes, nostrils, and mouth."}},{"museum_id":"cleveland","language":"en","id":"cma-1950-86","position":24,"title":"Buddha of the Future (Miroku Bosatsu)","category":"Japanese Art","subtitle":null,"artist":null,"facts":[{"label":"Date","value":"late 600s"},{"label":"Medium","value":"cast bronze, incised, with traces of gilding"},{"label":"Culture","value":"Japan, Asuka period (538–710)"},{"label":"Accession","value":"1950.86"}],"object_url":"https://clevelandart.org/art/1950.86","image":{"src":"/images/cleveland/cma-1950-86.jpg","sourceUrl":"https://clevelandart.org/art/1950.86","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"Buddhism was introduced to Japan in the sixth century. For early Japanese devotees, Buddhism offered the promise of salvation through faith in the Buddha of the Future, who would appear at the end of the world. The concept of eternal salvation held particular resonance with the Japanese aristocracy, who became the staunchest supporters of this new faith. Small sculptures like this one, with its gentle grace and powerful presence, were popular devotional objects."}},{"museum_id":"cleveland","language":"en","id":"cma-1952-286","position":25,"title":"Swift Bull from the Ten Swift Bulls","category":"Japanese Art","subtitle":null,"artist":null,"facts":[{"label":"Date","value":"late 1200s–early 1300s"},{"label":"Medium","value":"section of a handscroll mounted as a hanging scroll; ink and slight color on paper"},{"label":"Culture","value":"Japan, Kamakura period (1185–1333)"},{"label":"Accession","value":"1952.286"}],"object_url":"https://clevelandart.org/art/1952.286","image":{"src":"/images/cleveland/cma-1952-286.jpg","sourceUrl":"https://clevelandart.org/art/1952.286","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"Across the world, animals once played a much larger role in the transportation of the elite. Members of Japan’s imperial court traveled in vehicles pulled by oxen until the late 1400s, when oxcarts were restricted to ceremonial use. One sign of the past importance of the ox as a status symbol survives in this fragment from a scroll of portraits of 10 speedy bulls. The painter layered washes containing differing ratios of black ink to water to create a three-dimensional effect."}},{"museum_id":"cleveland","language":"en","id":"cma-1953-16","position":26,"title":"Mandala of the Three Shrines at Kumano","category":"Japanese Art","subtitle":null,"artist":null,"facts":[{"label":"Date","value":"1300s"},{"label":"Medium","value":"hanging scroll; ink and color on silk"},{"label":"Culture","value":"Japan, Kamakura period (1185–1333) to Nanbokuchō period (1336–92)"},{"label":"Accession","value":"1953.16"}],"object_url":"https://clevelandart.org/art/1953.16","image":{"src":"/images/cleveland/cma-1953-16.jpg","sourceUrl":"https://clevelandart.org/art/1953.16","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"This painting depicts the three shrines of Kumano from a bird’s-eye perspective, with the Buddhist counterparts of the kami of each shrine hall shown in discs directly above the halls. It also features figures, both pilgrims and deities, along the pilgrimage route and at the shrines. It is the only surviving work illustrating architectural representations of all three shrines in the same painting. They are compressed into a stacked composition, with the Nachi shrine at the top, the Shingū in the middle, and the Hongū at the bottom."}},{"museum_id":"cleveland","language":"en","id":"cma-1953-358","position":27,"title":"The Story of Fukutomi","category":"Japanese Art","subtitle":null,"artist":null,"facts":[{"label":"Date","value":"mid-1400s"},{"label":"Medium","value":"Handscroll; ink and color on paper"},{"label":"Culture","value":"Japan, Muromachi period (1392–1573)"},{"label":"Accession","value":"1953.358"}],"object_url":"https://clevelandart.org/art/1953.358","image":{"src":"/images/cleveland/cma-1953-358.jpg","sourceUrl":"https://clevelandart.org/art/1953.358","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"This handscroll shows the second half of an odd tale in which a ne’er-do-well seeks the path to quick fortune and learns the art of musical flatulence. Prior to a major performance, a mentor (and competitor) advises him to consume morning glory seeds, a laxative. Thus, while performing he fouls himself and ends his days in humiliation. The audacious nature of this story and its presentation—well-animated figures with dialogue adjacent to the appropriate moments of action—create a primitive graphic novel. Japanese visual humor about farting preceded this story, but the satirical, mean-spirited twist in this tale suggests its intent was not merely to be humorous. The story was likely commissioned by court officials who disapproved of common performers rising to high positions, outflanking what was the accepted social order."}},{"museum_id":"cleveland","language":"en","id":"cma-1956-87","position":28,"title":"The Illustrated Miraculous Origins of the Yūzū Nenbutsu School","category":"Japanese Art","subtitle":null,"artist":null,"facts":[{"label":"Date","value":"early 1300s"},{"label":"Medium","value":"Handscroll; ink, color, and gold on paper"},{"label":"Culture","value":"Japan, Kamakura period (1185–1333)"},{"label":"Accession","value":"1956.87"}],"object_url":"https://clevelandart.org/art/1956.87","image":{"src":"/images/cleveland/cma-1956-87.jpg","sourceUrl":"https://clevelandart.org/art/1956.87","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"This painting is the second of a set of two illustrated handscrolls. The first scroll depicts the biography of the Japanese Buddhist monk Ryōnin. This scroll begins with scenes of Ryōnin’s death and relates episodes illustrating the efficacy of following his teachings. Ryōnin asserted the total interconnectedness of all things and the spiritual benefit of chanting the name of the Buddha Amida for one another."}},{"museum_id":"cleveland","language":"en","id":"cma-1959-136","position":29,"title":"Dragon and Tiger","category":"Japanese Art","subtitle":null,"artist":"Sesson Shūkei (Japanese, c. 1492–c. 1577)","facts":[{"label":"Date","value":"c. 1546–56"},{"label":"Medium","value":"Pair of six-panel folding screens; ink on paper"},{"label":"Accession","value":"1959.136"}],"object_url":"https://clevelandart.org/art/1959.136","image":{"src":"/images/cleveland/cma-1959-136.jpg","sourceUrl":"https://clevelandart.org/art/1959.136","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"A tiger sits in a bamboo grove whipped with fierce wind, while a dragon claws through clouds above rough waves. Tiger and dragon are Chinese cosmological symbols of the balancing forces in the world, yin (the feminine aspect) and yang (the masculine aspect). The tiger's roar is also said to generate wind, and the dragon clouds. The screens may have originally been meant to express the fluctuating nature of the world as envisioned in the practice of military divination, or forecasting, based on the Yijing (Book of Changes)."}},{"museum_id":"cleveland","language":"en","id":"cma-1961-48","position":30,"title":"Sun Bodhisattva (Nikkō Bosatsu)","category":"Japanese Art","subtitle":null,"artist":null,"facts":[{"label":"Date","value":"c. 800"},{"label":"Medium","value":"Japanese nutmeg-yew wood with traces of color and gold"},{"label":"Culture","value":"Japan, Heian period (794–1185)"},{"label":"Accession","value":"1961.48"}],"object_url":"https://clevelandart.org/art/1961.48","image":{"src":"/images/cleveland/cma-1961-48.jpg","sourceUrl":"https://clevelandart.org/art/1961.48","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"Bodhisattvas are beings who have attained enlightenment but delay entry into Buddhahood until they have fulfilled their varied vows to aid others along the path to enlightenment. The flowing robes and curving posture of this figure were inspired by Chinese Buddhist sculpture. However, the interplay of the wood grain in this single block of yew with the artist’s subtle carving is a Japanese innovation. Originally paired with the Moon Bodhisattva (Gekkō Bosatsu), this figure likely flanked a sculpture of the Medicine Master Buddha (Yakushi Nyorai)."}},{"museum_id":"cleveland","language":"en","id":"cma-1963-513","position":31,"title":"Cosmetics Box with Chrysanthemums","category":"Japanese Art","subtitle":null,"artist":null,"facts":[{"label":"Date","value":"early 1300s"},{"label":"Medium","value":"lacquer on wood"},{"label":"Culture","value":"Japan, Kamakura period (1185–1333)"},{"label":"Accession","value":"1963.513"}],"object_url":"https://clevelandart.org/art/1963.513","image":{"src":"/images/cleveland/cma-1963-513.jpg","sourceUrl":"https://clevelandart.org/art/1963.513","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"In China, the chrysanthemum was historically appreciated for its association with the Double Nine Festival and the reclusive life of the poet Tao Yuanming (AD 365-427). In Japan, the 16-petaled chrysanthemum came to symbolize the Japanese imperial family after Emperor Gotoba (1180-1239) chose the motif as his personal emblem, having it applied to his sword and everyday utensils. This box proves that the flower also appeared on lacquer wares as early as the Kamakura period."}},{"museum_id":"cleveland","language":"en","id":"cma-1964-386","position":32,"title":"Paulownias and Chrysanthemums","category":"Japanese Art","subtitle":null,"artist":"Sakai Hōitsu (Japanese, 1761–1828)","facts":[{"label":"Date","value":"early 1800s"},{"label":"Medium","value":"Two-panel folding screen; ink and color on gilded paper"},{"label":"Accession","value":"1964.386"}],"object_url":"https://clevelandart.org/art/1964.386","image":{"src":"/images/cleveland/cma-1964-386.jpg","sourceUrl":"https://clevelandart.org/art/1964.386","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"In this screen, Sakai Hōitsu expertly deployed a painting technique called “dripping-in” (tarashikomi). Ink and color dripped on the surface, and allowed to pool there, created the illusionistic effect of lichen-dotted tree bark and twisted chrysanthemum leaves. Paulownia and chrysanthemum are signifiers of late spring and early autumn as well as emblems of the Japanese imperial house. Paulownia also has medicinal properties and associations with fortitude, while chrysanthemum symbolizes good government."}},{"museum_id":"cleveland","language":"en","id":"cma-1966-118","position":33,"title":"Selections from the New Collection of Japanese Poems from Ancient and Modern Times (Shinkokin wakashū) with Printed Designs of Chinese Lions and Crab Finger Grass","category":"Japanese Art","subtitle":null,"artist":"Hon'ami Kōetsu (Japanese, 1558–1637) · Tawaraya Sōtatsu (Japanese, c. 1570–c. 1640)","facts":[{"label":"Date","value":"early 1600s"},{"label":"Medium","value":"handscroll; ink, gold, and silver on paper"},{"label":"Accession","value":"1966.118"}],"object_url":"https://clevelandart.org/art/1966.118","image":{"src":"/images/cleveland/cma-1966-118.jpg","sourceUrl":"https://clevelandart.org/art/1966.118","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"Hon’ami Kōetsu was a calligrapher and craftsman who frequently collaborated with the painter Tawaraya Sōtatsu, considered the first master of the Rinpa school. Kōetsu brushed seven poems from the autumn section of a poetry anthology onto dyed paper with motifs designed and printed in gold and silver by Sōtatsu."}},{"museum_id":"cleveland","language":"en","id":"cma-1969-130","position":34,"title":"Repository for the Great Perfection of Wisdom Sutra and Eleven Volumes of the Great Perfection of Wisdom Sutra","category":"Japanese Art","subtitle":null,"artist":null,"facts":[{"label":"Date","value":"late 1100s"},{"label":"Medium","value":"lacquered wood with ink, color, gold, cut gold, and metalwork"},{"label":"Culture","value":"Japan, Heian period (794–1185)"},{"label":"Accession","value":"1969.130"}],"object_url":"https://clevelandart.org/art/1969.130","image":{"src":"/images/cleveland/cma-1969-130.jpg","sourceUrl":"https://clevelandart.org/art/1969.130","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"This repository is one of a pair that once contained the scrolls of a religious text called the Great Perfection of Wisdom Sutra. Two discs painted on the back have the sacred syllables representing the Buddha Shakyamuni and the Buddha Amida. Eight of the 16 benevolent but fierce looking deities who protect the text appear on the doors."}},{"museum_id":"cleveland","language":"en","id":"cma-1970-67","position":35,"title":"Portrait of Hottō Enmyō Kokushi","category":"Japanese Art","subtitle":null,"artist":null,"facts":[{"label":"Date","value":"c. 1295–1315"},{"label":"Medium","value":"Hinoki cypress wood with lacquer, metal staples and fittings"},{"label":"Culture","value":"Japan, Kamakura period (1185–1333)"},{"label":"Accession","value":"1970.67"}],"object_url":"https://clevelandart.org/art/1970.67","image":{"src":"/images/cleveland/cma-1970-67.jpg","sourceUrl":"https://clevelandart.org/art/1970.67","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"Hottō Enmyō Kokushi, is a posthumous title bestowed upon the Zen Buddhist monk Shinchi Kakushin (1203–1298) by the emperor Go-Daigo. The title means “perfectly awakened national teacher of the Dharma lamp.” Considered a fine example of “Kamakura realism,” while downplaying detail in the body, the sculpture emphasizes fidelity in representing the visage of Kakushin."}},{"museum_id":"cleveland","language":"en","id":"cma-1973-18","position":36,"title":"Storage Jar","category":"Japanese Art","subtitle":null,"artist":null,"facts":[{"label":"Date","value":"late 1300s–1400s"},{"label":"Medium","value":"Stoneware with natural ash glaze (Shigaraki ware)"},{"label":"Culture","value":"Japan, Muromachi period (1392–1573)"},{"label":"Accession","value":"1973.18"}],"object_url":"https://clevelandart.org/art/1973.18","image":{"src":"/images/cleveland/cma-1973-18.jpg","sourceUrl":"https://clevelandart.org/art/1973.18","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"The red color of this jar comes from iron in the clay. Natural ash glaze settled on the vessel during firing. The rim would have been complete with a slightly flared lip. Around the collar is an incised pattern resembling cypress fences, a common scene in the Japanese landscape. Intended for grain storage, rustic vessels like this one were also prized by tea enthusiasts, who appreciated the uncalculated beauty of the glaze and the asymmetry of these humble vessels."}},{"museum_id":"cleveland","language":"en","id":"cma-1918-501","position":37,"title":"Amitabha Triad","category":"Korean Art","subtitle":null,"artist":null,"facts":[{"label":"Date","value":"1400s"},{"label":"Medium","value":"bronze with traces of gilding"},{"label":"Culture","value":"Korea, Joseon dynasty (1392–1910)"},{"label":"Accession","value":"1918.501"}],"object_url":"https://clevelandart.org/art/1918.501","image":{"src":"/images/cleveland/cma-1918-501.jpg","sourceUrl":"https://clevelandart.org/art/1918.501","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"This bronze triad depicts Amitabha, the Buddha of Western Paradise, at the center, flanked by two bodhisattvas: Ksitigarbha on his left and Avalokiteśvara on his right. Ksitigarbha is believed to rescue those tormented beings from purgatory, while Avalokiteśvara offers relief to those suffering in the mortal realm. An exceptionally rare statue from the 1400s, this piece entered the CMA’s collection in 1918. It was discovered in Korea in 1916 by Langdon Warner (1881–1955), who was serving as the CMA’s field agent. In a letter dated December 4, 1916, Warner expressed not only his excitement upon finding the triad in a local pawn shop but also his satisfaction at purchasing it at a significantly reduced price."}},{"museum_id":"cleveland","language":"en","id":"cma-1921-631","position":38,"title":"Water Ewer for Rituals (Kundika) with Incised Parrot Design","category":"Korean Art","subtitle":null,"artist":null,"facts":[{"label":"Date","value":"1100s"},{"label":"Medium","value":"stoneware with celadon glaze, incised and carved decoration"},{"label":"Culture","value":"Korea, Goryeo dynasty (918–1392)"},{"label":"Accession","value":"1921.631"}],"object_url":"https://clevelandart.org/art/1921.631","image":{"src":"/images/cleveland/cma-1921-631.jpg","sourceUrl":"https://clevelandart.org/art/1921.631","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"This distinctively shaped celadon vessel is a kundika. With a spout on one side, this type of vessel is often used in Buddhist purification rituals. Unlike most existing examples that have an image of a willow tree, this work has a rare flying phoenix design incised on its surface. During the Goryeo period (918-1392), about 260 kilns operated in mainly Jeolla and Chungcheong provinces, meeting a soaring demand for high-end products like this example."}},{"museum_id":"cleveland","language":"en","id":"cma-1928-179","position":39,"title":"Wine Ewer with Incised Bamboo Shoot Design","category":"Korean Art","subtitle":null,"artist":null,"facts":[{"label":"Date","value":"1100s"},{"label":"Medium","value":"celadon ware with incised decoration"},{"label":"Culture","value":"Korea, Goryeo dynasty (918–1392)"},{"label":"Accession","value":"1928.179"}],"object_url":"https://clevelandart.org/art/1928.179","image":{"src":"/images/cleveland/cma-1928-179.jpg","sourceUrl":"https://clevelandart.org/art/1928.179","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"Natural motifs inspired the shape of celadon vessels as well as their inlaid designs in the Goryeo period. This wine ewer is shaped like a bamboo shoot, but it also resembles a lotus bud. Even though the spout was repaired, the ewer is a masterpiece of Goryeo period celadon. Ewers of the same shape are now housed at the National Museum of Korea and the Museum of Oriental Ceramics, Osaka."}},{"museum_id":"cleveland","language":"en","id":"cma-1979-71","position":40,"title":"Arhat","category":"Korean Art","subtitle":null,"artist":null,"facts":[{"label":"Date","value":"1235"},{"label":"Medium","value":"Hanging scroll; ink and slight color on silk"},{"label":"Culture","value":"Korea, Goryeo dynasty (918–1392)"},{"label":"Accession","value":"1979.71"}],"object_url":"https://clevelandart.org/art/1979.71","image":{"src":"/images/cleveland/cma-1979-71.jpg","sourceUrl":"https://clevelandart.org/art/1979.71","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"An arhat (Nahan in Korean), an advanced disciple of the Buddha, is represented here in profile with a halo encircling his head. This particular arhat is Segongyang jonja, numbered as the 464th of 500 arhats. He sits on a woven bamboo stool, is luring a dragon into an alms bowl. This hanging scroll is one of only about ten known works that survive today, all of which (except for Cleveland’s piece) are currently preserved in Korea or Japan."}},{"museum_id":"cleveland","language":"en","id":"cma-1985-112","position":41,"title":"Basin with Inscribed Figures and Calligraphy","category":"Korean Art","subtitle":null,"artist":null,"facts":[{"label":"Date","value":"1100s–1200s"},{"label":"Medium","value":"bronze"},{"label":"Culture","value":"Korea, Goryeo dynasty (918–1392)"},{"label":"Accession","value":"1985.112"}],"object_url":"https://clevelandart.org/art/1985.112","image":{"src":"/images/cleveland/cma-1985-112.jpg","sourceUrl":"https://clevelandart.org/art/1985.112","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"This bronze basin may have been used for containing purified water. What makes this work charming is its intricate decoration done in silver inlay: the five-character, four-line poems interspersed among images of a child. The poems, which evoke the concept of nonattachment and nonduality, were written by Buddhist monks."}},{"museum_id":"cleveland","language":"en","id":"cma-1986-45","position":42,"title":"Winter Landscape","category":"Korean Art","subtitle":null,"artist":"Yeoseol (Korean)","facts":[{"label":"Date","value":"1500s"},{"label":"Medium","value":"hanging scroll; ink and slight color on silk"},{"label":"Accession","value":"1986.45"}],"object_url":"https://clevelandart.org/art/1986.45","image":{"src":"/images/cleveland/cma-1986-45.jpg","sourceUrl":"https://clevelandart.org/art/1986.45","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"This wintry vista is a vivid example of idealistic monumental painting: the strong contrasts of ink washes and contouring brush lines; the bold outlining of rock shapes and tree trunks; and the many short, twisting brushstrokes that build up the surfaces of the rocks. Much of the painting’s appeal can be attributed to the dynamic lines and contrasting tonal patterns that lead the viewer’s eye from the lower foreground toward the cold mountain peaks in the distance. In the corner is a seal that reads \"Yeoseol,\" meaning \"Snow-Like.\""}},{"museum_id":"cleveland","language":"en","id":"cma-1986-69","position":43,"title":"Jar with Dragon and Clouds Design","category":"Korean Art","subtitle":null,"artist":null,"facts":[{"label":"Date","value":"late 1600s"},{"label":"Medium","value":"porcelain with underglaze iron"},{"label":"Culture","value":"Korea, Joseon dynasty (1392–1910)"},{"label":"Accession","value":"1986.69"}],"object_url":"https://clevelandart.org/art/1986.69","image":{"src":"/images/cleveland/cma-1986-69.jpg","sourceUrl":"https://clevelandart.org/art/1986.69","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"In traditional Korean art, dragons were used as an emblem of royalty. Over centuries, the ways of depicting this powerful mythical creature varied in response to artistic trends and socioeconomic changes. Here, the artist imagined with free-flowing calligraphic brushstrokes a whimsical dragon with bulging eyes who wraps his scaled body around the vessel. This piece was acquired from the London Gallery in Tokyo, Japan. Its owner, Tajima Mitsuru (born about 1936) is regarded as one of the pioneering Japanese art dealers to cultivate lasting relationships directly with collectors and museums in the United States."}},{"museum_id":"cleveland","language":"en","id":"cma-1986-85","position":44,"title":"Jar with Dragon Design","category":"Korean Art","subtitle":null,"artist":null,"facts":[{"label":"Date","value":"1700s"},{"label":"Medium","value":"porcelain with underglaze blue"},{"label":"Culture","value":"Korea, Joseon dynasty (1392–1910)"},{"label":"Accession","value":"1986.85"}],"object_url":"https://clevelandart.org/art/1986.85","image":{"src":"/images/cleveland/cma-1986-85.jpg","sourceUrl":"https://clevelandart.org/art/1986.85","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"As a mythical creature believed to make rain, the dragon served as a symbol of rulers in premodern East Asia. Here, a cobalt blue dragon is depicted flying through clouds to catch a flaming, wish-granting jewel called a cintamani. In the royal court, the shorter type of dragon jar held wine, while the tall type, like this one, held flowers. This porcelain once belonged to Robert W. Moore, who developed an interest in Korean art while serving in the US Army in South Korea during the 1950s and 1960s. Later, the CMA acquired this important work through an auction sale in 1986."}},{"museum_id":"cleveland","language":"en","id":"cma-1987-187","position":45,"title":"Snowscape with Figures","category":"Korean Art","subtitle":null,"artist":"Kim Si (Korean, 1524–1593)","facts":[{"label":"Date","value":"1584"},{"label":"Medium","value":"hanging scroll; ink on silk"},{"label":"Accession","value":"1987.187"}],"object_url":"https://clevelandart.org/art/1987.187","image":{"src":"/images/cleveland/cma-1987-187.jpg","sourceUrl":"https://clevelandart.org/art/1987.187","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"This hanging scroll is a rare surviving example of early Joseon period painting. The painter Kim Si (1481–1537) was a member of the aristocracy, or high-ranking men. However, after his father, Kim Anro (1481–1537) fell out of power, Kim Si retreated himself and spent his life as a reclusive artist. In such a context, this image of a solitary scholar in his studio surrounded by trees and snow-covered mountains does not simply render an idealized life of a recluse focusing on scholarly pursuits; rather, it is the painter’s mindscape, indicating that the glory of his family has become a forgotten part of his past."}},{"museum_id":"cleveland","language":"en","id":"cma-1989-6","position":46,"title":"Seven Jeweled Mountain","category":"Korean Art","subtitle":null,"artist":null,"facts":[{"label":"Date","value":"late 1800s"},{"label":"Medium","value":"ten-panel screen; ink and color on silk"},{"label":"Culture","value":"Korea, Joseon dynasty (1392–1910)"},{"label":"Accession","value":"1989.6"}],"object_url":"https://clevelandart.org/art/1989.6","image":{"src":"/images/cleveland/cma-1989-6.jpg","sourceUrl":"https://clevelandart.org/art/1989.6","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"With a bird’s-eye view, this ten-panel folding screen portrays the famous Seven Jeweled Mountain 칠보산 in North Korea. Ancient volcanic eruptions shaped the mountain’s unique and awe-inspiring terrain such as phallic-shaped pillars (panel #5, from the right); a large flat-topped, steep-sided cliff (panels #7 and #8), and a rugged mountain composed of metamorphic and igneous rocks (panels #9 and #10). The tradition of landscape painting that details actual natural sites and captures their topographic features in Korea began in the 1700s and continued onward. While such natural wonders were beloved as popular destinations for tourism and pilgrimage, after the Korean War (1950–53), these sites in North Korea are no longer accessible to the outside world. This folding screen detailing the mountain’s distinctive topography feeds our imagination and longing for such an unattainable place."}},{"museum_id":"cleveland","language":"en","id":"cma-1994-25","position":47,"title":"Avatamsaka Sutra No. 78","category":"Korean Art","subtitle":null,"artist":null,"facts":[{"label":"Date","value":"1300s"},{"label":"Medium","value":"Folded book with illustrated frontispiece; gold and silver on mulberry paper"},{"label":"Culture","value":"Korea, Goryeo dynasty (918–1392)"},{"label":"Accession","value":"1994.25"}],"object_url":"https://clevelandart.org/art/1994.25","image":{"src":"/images/cleveland/cma-1994-25.jpg","sourceUrl":"https://clevelandart.org/art/1994.25","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"This illuminated manuscript presents one part of the multivolume sacred text titled Avatamsaka (Flower Garland) sutra. Both the script and the image are rendered in gold ink on the smooth surface of the dark blue, indigo-dyed mulberry paper. This portion of the text, which reads from right to left, describes the encounter of the Buddha of the Future (Maitreya) and the young pilgrim Sudhana. The Buddha gives his words of wisdom to Sudhana, who asks questions about the path toward spiritual awakening. Mixed with ink and glue, the gold has a brilliance that strikingly reflects Sudhana’s ardent quest for understanding the way to reach enlightenment."}},{"museum_id":"cleveland","language":"en","id":"cma-2011-37","position":48,"title":"Books and Scholars’ Accoutrements","category":"Korean Art","subtitle":null,"artist":"Yi Taek-gyun (Korean, 1808–after 1883)","facts":[{"label":"Date","value":"late 1800s"},{"label":"Medium","value":"ten-panel folding screen; ink and color on silk"},{"label":"Accession","value":"2011.37"}],"object_url":"https://clevelandart.org/art/2011.37","image":{"src":"/images/cleveland/cma-2011-37.jpg","sourceUrl":"https://clevelandart.org/art/2011.37","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"First produced around the second half of the eighteenth century, chaekgado (literally, “pictures of bookshelves”) flourished throughout the 1800s as a royal emblem. And soon this pictorial genre became a popular furnishing item for aristocrats' elegant studies. The third panel from the right bears a hidden seal that reveals the artist: Yi Taek-gyun, a prominent court artist active in the late 1800s."}},{"museum_id":"cleveland","language":"en","id":"cma-2015-138","position":49,"title":"Orchids and Rocks","category":"Korean Art","subtitle":null,"artist":"Yi Ha-eung (Korean, 1820–1898)","facts":[{"label":"Date","value":"1897–98"},{"label":"Medium","value":"Eight-panel folding screen; ink on silk"},{"label":"Accession","value":"2015.138"}],"object_url":"https://clevelandart.org/art/2015.138","image":{"src":"/images/cleveland/cma-2015-138.jpg","sourceUrl":"https://clevelandart.org/art/2015.138","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"Yi Ha-eung (1820−1898), the artist of this eight-panel folding screen, was one of the most influential men in late 19th-century Korea. Acting as the regent for his son, King Gojong (1852−1919), who ascended the throne at the age of thirteen, Yi ruled Korea from 1866 to 1873. In addition to his illustrious political career, Yi was also recognized as one of the most celebrated artists who led the revival of literati art in late 19th-century Korean art. In particular, he was recognized as the master of orchids, one of the “Four Gentlemen” (plum, orchid, chrysanthemum, and bamboo) themes. Solely relying on monochrome ink, Yi depicted the curvilinear silhouettes of cymbidium orchid leaves dramatically hanging down from cliffs. Growing in wilderness and redolent with fragrance, orchids were often associated with the perseverance of principled gentlemen, and thus became one of the most popular subjects of scholar-artists' paintings.On the upper right corner of the far left panel, Yi wrote a short inscription stating that he painted the work at the age of 80."}},{"museum_id":"cleveland","language":"en","id":"cma-2015-510","position":50,"title":"Grapevine","category":"Korean Art","subtitle":null,"artist":"Choe Seok-hwan (Korean, active first half of 19th century)","facts":[{"label":"Date","value":"early 1800s"},{"label":"Medium","value":"eight-panel folding screen; ink on paper"},{"label":"Accession","value":"2015.510"}],"object_url":"https://clevelandart.org/art/2015.510","image":{"src":"/images/cleveland/cma-2015-510.jpg","sourceUrl":"https://clevelandart.org/art/2015.510","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"July is the season of the ripening deep blue grapes, and also the month when the monsoon season begins in Korea. To the accompaniment of stormy summer wind, grape vines make a spectacular full circle across the surface of this eight-panel folding screen. The artist employed a variety of ink tones to create a sense of swift movement of grapevines amid turbulent storms. Since their first introduction to the Korean peninsula around the 7th century through the Silk Road, grapes were used as artistic motifs. Artists embellished the surface of mother-of-pearl lacquer boxes or blue-and-white porcelain, while scholar-poets composed poems about the luscious sweet sourness of green grapes. By the late 19th century, grapes became the icon of fertility: the fruit grows in large clusters of many individual grapes, evoking the image of a stable clan with many descendants."}},{"museum_id":"cleveland","language":"en","id":"cma-1926-554","position":51,"title":"Sir Anthony Mildmay, Knight of Apethorpe, Northamptonshire","category":"European Painting and Sculpture","subtitle":null,"artist":"Nicholas Hilliard (English, c. 1547–1619)","facts":[{"label":"Date","value":"c. 1590–93"},{"label":"Medium","value":"Watercolor on vellum, laid on card, mounted on wood"},{"label":"Accession","value":"1926.554"}],"object_url":"https://clevelandart.org/art/1926.554","image":{"src":"/images/cleveland/cma-1926-554.jpg","sourceUrl":"https://clevelandart.org/art/1926.554","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"Framed by the folds of a circular tent, Sir Anthony Mildmay strikes a relaxed and confident pose, with his right hand resting on a cloth-covered table and his left grasping the hilt of his thin, double-edged sword called a rapier. Helmet, gauntlet, and leg coverings are scattered about, as if Mildmay has been interrupted in the act of putting on or taking off his armor. Despite its small scale, this portrait reveals Nicholas Hilliard’s emulation of (and rivalry with) life-size court portraiture, while his meticulous attention to detail and use of costly materials like shell gold reflect the refined world of courtly tournaments."}},{"museum_id":"cleveland","language":"en","id":"cma-1937-577","position":52,"title":"The Sacrifice of Isaac","category":"European Painting and Sculpture","subtitle":null,"artist":"Andrea del Sarto (Italian, 1486–1530)","facts":[{"label":"Date","value":"c. 1527"},{"label":"Medium","value":"oil on wood"},{"label":"Accession","value":"1937.577"}],"object_url":"https://clevelandart.org/art/1937.577","image":{"src":"/images/cleveland/cma-1937-577.jpg","sourceUrl":"https://clevelandart.org/art/1937.577","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"In this dramatic test of faith from the Old Testament book of Genesis, Abraham agrees to slay his son Isaac on God’s command. As Abraham raises the knife, an angel suddenly appears to halt the sacrifice. This work gains its power from the complex expressions of father and son, combining grief, strength, resignation, fear, and realization in their faces and bodies, the latter inspired by ancient sculpture and Michelangelo. Andrea del Sarto never finished this painting, and it lays bare his working methods. He transferred the design to the panel from a drawing, reinforcing the chalk with painted lines—best seen in the donkey at the far right. He then worked over the whole panel at once with thin, brushy veils of color, letting him alter the composition while painting—especially evident in the angel, Isaac’s body, and Abraham’s head."}},{"museum_id":"cleveland","language":"en","id":"cma-1947-207","position":53,"title":"Portrait of Isabella Brant","category":"European Painting and Sculpture","subtitle":null,"artist":"Peter Paul Rubens (Flemish, 1577–1640)","facts":[{"label":"Date","value":"c. 1620–25"},{"label":"Medium","value":"oil on wood"},{"label":"Accession","value":"1947.207"}],"object_url":"https://clevelandart.org/art/1947.207","image":{"src":"/images/cleveland/cma-1947-207.jpg","sourceUrl":"https://clevelandart.org/art/1947.207","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"Isabella Brant was Rubens’s first wife. He painted her many times in many different ways before she died at the age of 35 (she is a model for a nymph in the other work by Rubens in this room). This intimate portrait, painted at least five years before her death, suggests the close relationship between the painter and sitter through the warm palette, the luscious brushstrokes, and her lively expression."}},{"museum_id":"cleveland","language":"en","id":"cma-1950-250","position":54,"title":"Portrait of a Man, Possibly Girolamo Rosati","category":"European Painting and Sculpture","subtitle":null,"artist":"Lorenzo Lotto (Italian, 1480–1556)","facts":[{"label":"Date","value":"1533–34"},{"label":"Medium","value":"oil on canvas"},{"label":"Accession","value":"1950.250"}],"object_url":"https://clevelandart.org/art/1950.250","image":{"src":"/images/cleveland/cma-1950-250.jpg","sourceUrl":"https://clevelandart.org/art/1950.250","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"The gesture of the elegantly dressed man is a mystery. Is he rising from his chair to address someone or is he pointing to something outside the frame? His right hand rests on a piece of paper (a letter?), while on the table are clover—a symbol of abundance, good fortune, and happy marriage—and jasmine, associated with purity and love, further emphasized by the roses on the trellis. There may have been a companion portrait of the sitter’s bride, to whom he acknowledges his devotion. Another recent interpretation identifies the sitter as Girolamo Rosati, a high official in Fermo, on Italy’s east coast. The paper may be a design for one of his important architectural projects, to which he may be pointing in the distance. The interrupted moment is a naturalistic touch characteristic of Lotto, quite distinct from the formality of the other Italian Renaissance portraits in the museum's collection. Though this portrait clearly articulates the man’s status, Lotto emphasizes his individuality and interiority as much as a socially constructed identity."}},{"museum_id":"cleveland","language":"en","id":"cma-1951-454","position":55,"title":"Saint Peter Repentant","category":"European Painting and Sculpture","subtitle":null,"artist":"Georges de La Tour (French, 1593–1652)","facts":[{"label":"Date","value":"1645"},{"label":"Medium","value":"oil on canvas"},{"label":"Accession","value":"1951.454"}],"object_url":"https://clevelandart.org/art/1951.454","image":{"src":"/images/cleveland/cma-1951-454.jpg","sourceUrl":"https://clevelandart.org/art/1951.454","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"During Jesus’s arrest on the night of the Last Supper, the apostle Peter denied knowing him. Although Christ forgave his betrayal, Peter was consumed by guilt. Georges de La Tour represents Peter as an old man, reflecting on his past actions in a state of perpetual repentance. The apostle’s red-rimmed eyes and the uncertain light of the lantern suggest anxious sleepless nights; muted colors and simple forms give visual expression to Peter’s somber emotions. Unlike other artists inspired by Caravaggio, La Tour worked in relative isolation in northeastern France, and his connection to his Italian counterpart remains unclear."}},{"museum_id":"cleveland","language":"en","id":"cma-1958-425","position":56,"title":"Hunting near Hartenfels Castle","category":"European Painting and Sculpture","subtitle":null,"artist":"Lucas Cranach the Elder (German, 1472–1553)","facts":[{"label":"Date","value":"1540"},{"label":"Medium","value":"oil, originally on wood, transferred to masonite"},{"label":"Accession","value":"1958.425"}],"object_url":"https://clevelandart.org/art/1958.425","image":{"src":"/images/cleveland/cma-1958-425.jpg","sourceUrl":"https://clevelandart.org/art/1958.425","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"The Protestant rulers of Saxony commissioned this animated hunt scene, set near their residence seen in the background, Hartenfels Castle (in eastern Germany). John Frederick the Magnanimous, in the bottom left corner, wears dark green hunting attire; he spans his crossbow and waits for his courtiers and dogs to chase a stag across the river. His wife, the Electress Sibylle, stands at right, poised to take the first ceremonial shot. The prince electors of Saxony were passionate practitioners of hunting with dogs—elaborate, highly rehearsed occasions, coordinated by the use of signals from hunting horns. Cranach dated this work and his signature is the winged snake at lower right. 1577 in the right corner is an inventory number."}},{"museum_id":"cleveland","language":"en","id":"cma-1960-117","position":57,"title":"Christ and the Virgin in the House at Nazareth","category":"European Painting and Sculpture","subtitle":null,"artist":"Francisco de Zurbarán (Spanish, 1598–1664)","facts":[{"label":"Date","value":"c. 1640"},{"label":"Medium","value":"oil on canvas"},{"label":"Accession","value":"1960.117"}],"object_url":"https://clevelandart.org/art/1960.117","image":{"src":"/images/cleveland/cma-1960-117.jpg","sourceUrl":"https://clevelandart.org/art/1960.117","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"Stories of Christ’s childhood and adolescence became increasingly popular during the Counter-Reformation because they were easily understood by a broad public. Rather than taking a story from the Bible, Zurbarán appears to have invented this subject, in which Jesus pricks himself on a crown of thorns he is weaving, foretelling his later torment at the Crucifixion. Despite the grand scale and monumental figures, the work has remarkable intimacy and quietness, emphasizing such details as the Virgin’s tears."}},{"museum_id":"cleveland","language":"en","id":"cma-1961-220","position":58,"title":"Portrait of Catherine Grey, Lady Manners","category":"European Painting and Sculpture","subtitle":null,"artist":"Thomas Lawrence (British, 1769–1830)","facts":[{"label":"Date","value":"1794"},{"label":"Medium","value":"oil on canvas"},{"label":"Accession","value":"1961.220"}],"object_url":"https://clevelandart.org/art/1961.220","image":{"src":"/images/cleveland/cma-1961-220.jpg","sourceUrl":"https://clevelandart.org/art/1961.220","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"The Irish poet Lady Manners rejected as “unflattering” this portrait representing her as the goddess Juno, symbolized here by the peacock. Thomas Lawrence exhibited the painting at the Royal Academy in 1794 with the label “to be disposed of [sold],” but it was still in the artist’s collection when he died. Though it offended Lady Manners, the painting displays all the hallmarks of Lawrence’s flamboyant style:dazzling, fluid brushwork and an innovative use of unconventional colors that helped secure his role as the most fashionable portrait painter in turn-of-the-century Britain."}},{"museum_id":"cleveland","language":"en","id":"cma-1965-15","position":59,"title":"Portrait of the Jester Calabazas","category":"European Painting and Sculpture","subtitle":null,"artist":"Diego Velázquez (Spanish, 1599–1660)","facts":[{"label":"Date","value":"c. 1631–32"},{"label":"Medium","value":"oil on canvas"},{"label":"Accession","value":"1965.15"}],"object_url":"https://clevelandart.org/art/1965.15","image":{"src":"/images/cleveland/cma-1965-15.jpg","sourceUrl":"https://clevelandart.org/art/1965.15","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"Calabazas, a jester in the court of King Philip IV of Spain, had physical and mental disabilities, a state that the artist emphasizes, rather than tries to hide. While the Spanish court prized and doted upon people with disabilities such as Calabazas, Velázquez transformed their depiction in portraiture. This startling work uses the format of the formal, full-length court portrait to present a type of person who was generally perceived as marginal at this point in history and profoundly humanizes him."}},{"museum_id":"cleveland","language":"en","id":"cma-1971-101","position":60,"title":"Danaë","category":"European Painting and Sculpture","subtitle":null,"artist":"Orazio Gentileschi (Italian, 1563–1639)","facts":[{"label":"Date","value":"c. 1623"},{"label":"Medium","value":"oil on canvas"},{"label":"Accession","value":"1971.101"}],"object_url":"https://clevelandart.org/art/1971.101","image":{"src":"/images/cleveland/cma-1971-101.jpg","sourceUrl":"https://clevelandart.org/art/1971.101","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"Danaë’s father feared a prophecy that his grandson would kill him, so he imprisoned his daughter to protect her from suitors. Yet Jupiter, king of the gods, fell in love with Danaë, and he came to her in the form of gold streaming from the sky. Gentileschi adopted Caravaggio’s method of painting directly from models, pulled to the front of the picture plane, which gives the painting a startling, tangible quality. However, the graceful way he handled paint and human gestures lends the work a poetic quality unique to the artist."}},{"museum_id":"cleveland","language":"en","id":"cma-1976-2","position":61,"title":"The Crucifixion of Saint Andrew","category":"European Painting and Sculpture","subtitle":null,"artist":"Caravaggio (Italian, 1571–1610)","facts":[{"label":"Date","value":"1606–7"},{"label":"Medium","value":"oil on canvas"},{"label":"Accession","value":"1976.2"}],"object_url":"https://clevelandart.org/art/1976.2","image":{"src":"/images/cleveland/cma-1976-2.jpg","sourceUrl":"https://clevelandart.org/art/1976.2","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"Saint Andrew’s efforts to introduce Christianity to Greece in the first century CE were met with hostility from local authorities. He was sentenced to die on the cross because he refused to acknowledge pagan gods. For two days, Andrew preached from his martyr’s station to an increasingly sympathetic crowd. Bowing to public demand, Andrew’s would-be executioners attempted to untie him, but their hands were mysteriously paralyzed. Andrew’s desire for martyrdom was thus fulfilled and he died enveloped in divine light. Caravaggio’s innovative interpretation involves the viewer more closely in the event by presenting the crucifixion as intimate and private, rather than as a gruesome public spectacle. Bold contrasts of light and dark suggest the presence of God. A masterpiece of Baroque painting, Caravaggio’s Crucifixion of Saint Andrew is the only altarpiece by the artist in America."}},{"museum_id":"cleveland","language":"en","id":"cma-1981-18","position":62,"title":"The Holy Family on the Steps","category":"European Painting and Sculpture","subtitle":null,"artist":"Nicolas Poussin (French, 1594–1665)","facts":[{"label":"Date","value":"1648"},{"label":"Medium","value":"oil on canvas"},{"label":"Accession","value":"1981.18"}],"object_url":"https://clevelandart.org/art/1981.18","image":{"src":"/images/cleveland/cma-1981-18.jpg","sourceUrl":"https://clevelandart.org/art/1981.18","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"This deceptively simple composition represents a complex meditation on the Holy Family’s role in the redemption of humanity. At the center, Mary presents the Christ child to the world. At the left, Saint Elizabeth leans forward to foretell his eventual death, while her son, Saint John the Baptist, offers Jesus an apple, signifying humanity’s fall from grace in the Garden of Eden. At the right, Saint Joseph holds a compass, a sign of his occupation as a carpenter and also symbolic of God the Father. Poussin developed his composition meticulously and deliberately, using clear primary colors, simple forms, and a geometric organization to express the central importance of the Holy Family in Christian belief."}},{"museum_id":"cleveland","language":"en","id":"cma-1999-173","position":63,"title":"Portrait of Tieleman Roosterman","category":"European Painting and Sculpture","subtitle":null,"artist":"Frans Hals (Dutch, c. 1581–1666)","facts":[{"label":"Date","value":"1634"},{"label":"Medium","value":"oil on canvas"},{"label":"Accession","value":"1999.173"}],"object_url":"https://clevelandart.org/art/1999.173","image":{"src":"/images/cleveland/cma-1999-173.jpg","sourceUrl":"https://clevelandart.org/art/1999.173","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"An extremely wealthy linen and silk merchant in Haarlem, Tieleman Roosterman was 36 years old when Frans Hals painted his portrait. Unlike many Dutch painters of the period, Hals favored strong, visible brushstrokes that convey the vitality of his sitters. Roosterman strikes a confident pose, his costume sober but luxurious: his sleeves are decorated with braid and buttons, and ribbon rosettes encircle the waist of his doublet. The rich black of his suit is offset by the broad linen collar and lace-edged cuffs—fashionable details befitting a successful cloth merchant."}},{"museum_id":"cleveland","language":"en","id":"cma-1931-205","position":64,"title":"Venus Reclining in a Landscape","category":"Prints","subtitle":null,"artist":"Giulio Campagnola (Italian, 1482–1515)","facts":[{"label":"Date","value":"c. 1508–9"},{"label":"Medium","value":"engraving"},{"label":"Accession","value":"1931.205"}],"object_url":"https://clevelandart.org/art/1931.205","image":{"src":"/images/cleveland/cma-1931-205.jpg","sourceUrl":"https://clevelandart.org/art/1931.205","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"The Venetian artist Giulio Campagnola introduced the \"dot manner,\" an engraving technique by which shading is created with dots and flicks produced with the point of the burin. This innovation allowed for a much greater range of tone and subtler gradations from dark to light. The effect imitated sfumato, a painting technique for creating soft atmospheric effects practiced by Venetian artists, such as Giorgione, at the time. The influence of and perhaps even the engraver’s collaboration with Giorgione is reflected in the extraordinary beauty and refinement of this rare early impression of Venus Reclining in a Landscape. The female nude reclining in a landscape was to become a distinctly Venetian subject in the 1500s."}},{"museum_id":"cleveland","language":"en","id":"cma-1941-71","position":65,"title":"In the Omnibus","category":"Prints","subtitle":null,"artist":"Mary Cassatt (American, 1844–1926)","facts":[{"label":"Date","value":"1890–91"},{"label":"Medium","value":"color drypoint and aquatint"},{"label":"Accession","value":"1941.71"}],"object_url":"https://clevelandart.org/art/1941.71","image":{"src":"/images/cleveland/cma-1941-71.jpg","sourceUrl":"https://clevelandart.org/art/1941.71","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"This print belongs to a series of color etchings created by Mary Cassatt between 1890 and 1891. Each was influenced by the artist's study of Japanese woodblock prints, especially in their use of flat planes of color and domestic subject matter. In the scene depicted here, a middle-class woman accompanies her nursemaid and child on errands throughout Paris. The group rides in an omnibus, a form of public transportation where different genders and classes could intermingle. While the nanny's attention stays focused on her young charge, the female subject appears distracted, gazing toward the world beyond."}},{"museum_id":"cleveland","language":"en","id":"cma-1949-565","position":66,"title":"View of Venice","category":"Prints","subtitle":null,"artist":"Jacopo de' Barbari (Italian, c. 1460/70–c. 1516) · Anton Kolb (German, 1474–1566)","facts":[{"label":"Date","value":"1500"},{"label":"Medium","value":"woodcut from six blocks on six sheets of paper"},{"label":"Accession","value":"1949.565"}],"object_url":"https://clevelandart.org/art/1949.565","image":{"src":"/images/cleveland/cma-1949-565.jpg","sourceUrl":"https://clevelandart.org/art/1949.565","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"By the end of the 1400s, Venice had emerged as the major printing center in Europe, where books were printed in various languages to be shipped around the world. The city also became the great emporium for prints, and the woodcut developed beyond its humble origins as a popular art for devotional imagery, playing cards, and later for book illustration. View of Venice epitomizes this new ambitious scope for the woodcut, and is a landmark in the history of printmaking. This monumental print can be compared in scale only to a mural decoration and presumably served as a less expensive surrogate for paintings. The six sheets that make up the design would have been pasted either onto a canvas or the wall itself, resulting in the survival of only 12 impressions of the original edition like this one, and only three in America. The goal of the print was to depict Venice as seen from above. No single vantage point would have been sufficient, so Jacopo de' Barbari and a team of surveyors climbed various towers and tall buildings to record small sections of the city. These individual views were combined to form the map which follows a single, though inconsistent, system of perspective. Unprecedented for its exactness of detail and difficulty of execution, View of Venice represents the first attempt to render the image of a city according to the laws of geometry. The view also highlights the seafaring trade activities of Venice, depicting Mercury, god of commerce, presiding over the city, while Neptune, god of the seas, keeps watch over the entrance to the city's Grand Canal."}},{"museum_id":"cleveland","language":"en","id":"cma-1950-72","position":67,"title":"Equestrian Portrait of the Emperor Maximilian","category":"Prints","subtitle":null,"artist":"Hans Burgkmair (German, 1473–1531)","facts":[{"label":"Date","value":"1508"},{"label":"Medium","value":"woodcut, in black and white on paper washed blue"},{"label":"Accession","value":"1950.72"}],"object_url":"https://clevelandart.org/art/1950.72","image":{"src":"/images/cleveland/cma-1950-72.jpg","sourceUrl":"https://clevelandart.org/art/1950.72","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"Presented in full profile, the Holy Roman Emperor Maximilian I (reigned 1486–1519) and his mount emulate a classical equestrian portrait statue. The Latin abbreviations inscribed at the top of the page describe him as “August Emperor Caesar Maximilian,” a title conceptually equating him with the leaders of the ancient Roman Empire. The two-headed eagle on the banner is the emblem of his dynastic family, the Hapsburgs. This exceptionally rare chiaroscuro woodcut— printed with black and white inks on paper prepared with tinted wash—represents one of the earliest experiments with this technique. Of the two surviving impressions printed on hand-colored paper, this is the only one that is blue."}},{"museum_id":"cleveland","language":"en","id":"cma-1951-349","position":68,"title":"Enclosed Valley","category":"Prints","subtitle":null,"artist":"Hercules Seghers (Dutch, 1589/90–c. 1638)","facts":[{"label":"Date","value":"c. 1623–30"},{"label":"Medium","value":"etching on cloth, hand colored with watercolor"},{"label":"Accession","value":"1951.349"}],"object_url":"https://clevelandart.org/art/1951.349","image":{"src":"/images/cleveland/cma-1951-349.jpg","sourceUrl":"https://clevelandart.org/art/1951.349","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"To make his dreamy and mysterious landscapes, Hercules Seghers combined a number of etching and coloring techniques in order to make prints that met his expressive ends, and which he considered printed paintings. He created 54 etchings, but instead of producing standardized editions printed in black ink on white paper, he made each impression a unique and individualized work of art. He often printed in colored inks on paper prepared with a colored ground, or on cloth (as here), and then painted the printed impression by hand. Cleveland’s etching is one of only ten known impressions of the first state of this print."}},{"museum_id":"cleveland","language":"en","id":"cma-1952-296","position":69,"title":"The Submersion of Pharaoh's Army in the Red Sea","category":"Prints","subtitle":null,"artist":"Titian (Italian, c. 1488–1576) · Domenico dalle Greche (Italian, 1503–1603)","facts":[{"label":"Date","value":"1514–15, printed 1549"},{"label":"Medium","value":"woodcut"},{"label":"Accession","value":"1952.296"}],"object_url":"https://clevelandart.org/art/1952.296","image":{"src":"/images/cleveland/cma-1952-296.jpg","sourceUrl":"https://clevelandart.org/art/1952.296","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"This composition is made up of 12 separately printed woodcuts to create one image in grand scale. The size rivals that of a history painting, and, unlike most prints, the composition would have been hung on the wall. This is confirmed by the lack of complete impressions from the date of the print's creation—around 1515. This and all extant impressions date from a later edition, published in 1549 by the publisher Domenico dalle Greche (Italian, active 1543–1558). The woodcut is based on a drawing by the Venetian master Titian, and the bold, expressive, and irregular marks of the woodcutter imitate his drawing manner. The narrative—that of the Israelites’ persecution under the Egyptian pharaoh and his army’s fate when they followed Moses into the Red Sea—is propelled across the 12 sheets with remarkable unity. The rolling clouds and turbulent sea culminate in the solid gravity of the magnificent cliff that overhangs the shore."}},{"museum_id":"cleveland","language":"en","id":"cma-1954-337","position":70,"title":"Bastille Day","category":"Prints","subtitle":null,"artist":"Maurice Prendergast (American, born Newfoundland [now Canada], 1858–1924)","facts":[{"label":"Date","value":"1892"},{"label":"Medium","value":"color monotype"},{"label":"Accession","value":"1954.337"}],"object_url":"https://clevelandart.org/art/1954.337","image":{"src":"/images/cleveland/cma-1954-337.jpg","sourceUrl":"https://clevelandart.org/art/1954.337","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"Maurice Prendergast began to make monotypes in the early 1890s while living in Paris, where he was influenced by Edgar Degas's use of the technique. Prendergast focused on scenes from daily life, such as this depiction of crowds filling the streets of the French capital on the country's national holiday. He used layers of blue and black ink to evoke the shadowy tones of nighttime and orbs of bright pink to suggest the artificial light of lanterns illuminating the boulevards."}},{"museum_id":"cleveland","language":"en","id":"cma-1959-82","position":71,"title":"Evening, Melancholy I","category":"Prints","subtitle":null,"artist":"Edvard Munch (Norwegian, 1863–1944)","facts":[{"label":"Date","value":"1896"},{"label":"Medium","value":"Hand-colored woodcut"},{"label":"Accession","value":"1959.82"}],"object_url":"https://clevelandart.org/art/1959.82","image":{"src":"/images/cleveland/cma-1959-82.jpg","sourceUrl":"https://clevelandart.org/art/1959.82","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"Evening, Melancholy I depicts the jilted, tormented art critic Jappe Nilssen, Munch's friend, on the shore of Åsgårdstrand, a fishing village south of Oslo. Munch chose heavily grained blocks of wood, allowing the pattern of the board to add texture to the scene, and he exploited the handmade aspect of the technique by carving blocks crudely. He also experimented so that each impression is unique, using black ink on the woodblock and watercolor and gouache to color the sheet extensively. An example of how method can reinforce meaning, the simplified shapes, flattened space, and dark hues create a visual correspondence to the figure's deep depression."}},{"museum_id":"cleveland","language":"en","id":"cma-1959-241","position":72,"title":"Christ Crucified Between the Two Thieves: 'The Three Crosses'","category":"Prints","subtitle":null,"artist":"Rembrandt van Rijn (Dutch, 1606–1669)","facts":[{"label":"Date","value":"1653-c.1660"},{"label":"Medium","value":"drypoint"},{"label":"Accession","value":"1959.241"}],"object_url":"https://clevelandart.org/art/1959.241","image":{"src":"/images/cleveland/cma-1959-241.jpg","sourceUrl":"https://clevelandart.org/art/1959.241","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"Rembrandt’s Christ Crucified Between the Two Thieves is executed entirely in drypoint. Because of the delicacy of the technique, the copper plate was worn after the artist printed about 40 impressions of the first three states. In order to continue using the plate, Rembrandt reworked it, changing the image somewhat. In this fourth state, slashing strokes obscure the spectators visible in the earlier version, creating a tenebrous setting that focuses attention on Christ bathed in celestial light. Although drypoint is an inherently linear medium, Rembrandt used it to obtain tonal qualities associated with painting. The blackness becomes an active force that threatens to extinguish the light of Christ—a literal illustration of the Evangelist Luke’s description of the event that brought \"a darkness over all the earth.\""}},{"museum_id":"cleveland","language":"en","id":"cma-1966-177","position":73,"title":"Estérel Village","category":"Prints","subtitle":null,"artist":"Edgar Degas (French, 1834–1917)","facts":[{"label":"Date","value":"c. 1890"},{"label":"Medium","value":"color monotype"},{"label":"Accession","value":"1966.177"}],"object_url":"https://clevelandart.org/art/1966.177","image":{"src":"/images/cleveland/cma-1966-177.jpg","sourceUrl":"https://clevelandart.org/art/1966.177","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"This landscape is one of many monotypes that Edgar Degas produced throughout his career. The work belongs to a series Degas made while visiting a friend in the French countryside. Its blurriness resembles the view he saw out the window of trains and carriages during his travels. To translate the effects of weather and the natural terrain, he created layers of color and texture that border on abstraction in the final composition."}},{"museum_id":"cleveland","language":"en","id":"cma-1967-127","position":74,"title":"Battle of the Nudes","category":"Prints","subtitle":null,"artist":"Antonio del Pollaiuolo (Italian, 1431/32–1498)","facts":[{"label":"Date","value":"1470s–80s"},{"label":"Medium","value":"engraving"},{"label":"Accession","value":"1967.127"}],"object_url":"https://clevelandart.org/art/1967.127","image":{"src":"/images/cleveland/cma-1967-127.jpg","sourceUrl":"https://clevelandart.org/art/1967.127","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"This engraving is one of the earliest Renaissance prints to portray the nude male body in action. Antonio del Pollaiuolo’s grimacing warriors appear like clones in different poses. The print may have functioned as a model for workshop apprentices studying human anatomy while learning to draw; however, the artist’s Latin signature suggests it also had an audience educated in literature. Art historians remain uncertain whether Pollaiuolo intended to depict a particular story or historical event. It is possible he created a deliberately ambiguous allegory that would appeal to patrons interested in interpreting symbols. For example, the continuous chain shared by the two central men could refer to an ancient idea that the body is the chain of the soul, only to be released in death."}},{"museum_id":"cleveland","language":"en","id":"cma-2003-46","position":75,"title":"The Cathedral","category":"Prints","subtitle":null,"artist":"James Ensor (Belgian, 1860–1949)","facts":[{"label":"Date","value":"1886"},{"label":"Medium","value":"etching"},{"label":"Accession","value":"2003.46"}],"object_url":"https://clevelandart.org/art/2003.46","image":{"src":"/images/cleveland/cma-2003-46.jpg","sourceUrl":"https://clevelandart.org/art/2003.46","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"James Ensor used tiny, repetitive marks possible with etching to develop a new, expressive style that contrasted with that of most of his contemporaries. The Gothic architecture, worn facade, and overwhelming scale of the cathedral seen here in exacting detail show that it has withstood the test of time. Ensor juxtaposed the building with a dense crowd of grotesque figures that push forward seemingly irrationally, presenting a symbolic contrast between their whims and the permanence of both the church and the past."}},{"museum_id":"cleveland","language":"en","id":"cma-2004-87","position":76,"title":"Self-Portrait","category":"Prints","subtitle":null,"artist":"Edgar Degas (French, 1834–1917)","facts":[{"label":"Date","value":"1857"},{"label":"Medium","value":"etching and drypoint"},{"label":"Accession","value":"2004.87"}],"object_url":"https://clevelandart.org/art/2004.87","image":{"src":"/images/cleveland/cma-2004-87.jpg","sourceUrl":"https://clevelandart.org/art/2004.87","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"In the 1850s Degas frequently used himself as a model, but he made only one printed self-portrait. Through successive stages of biting the plate and layers of crosshatching, Degas gradually built areas of dark tone. In this impression, Degas added etched lines on the face, hat, and coat and carefully wiped his copper plate to create atmospheric effects. His clearly drawn eyes directly engage the viewer, resulting in a psychologically powerful and intense portrait of the young artist at age 23. This impression was dedicated to his friend, the painter and sculptor Paul Albert Bartholomé."}},{"museum_id":"cleveland","language":"en","id":"cma-1947-183","position":77,"title":"Set of Four Armchairs and Settee","category":"Decorative Art and Design","subtitle":null,"artist":"Royal Savonnerie Manufactory, Chaillot Workshops (French, est. 1627)","facts":[{"label":"Date","value":"c. 1715"},{"label":"Medium","value":"carved wood, Savonnerie knotted-pile (symmetrical rug knot) upholstery; wool, hemp"},{"label":"Accession","value":"1947.183"}],"object_url":"https://clevelandart.org/art/1947.183","image":{"src":"/images/cleveland/cma-1947-183.jpg","sourceUrl":"https://clevelandart.org/art/1947.183","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"These chairs belong to a suite that includes a settee (also in the CMA’s collection) and a tapestry made for a count and countess to mark their wedding in 1717. Furniture of this scale was usually placed against the wall in grand reception halls, more as a display of wealth than for use. Upholstered in Savonnerie tapestries, this suite was among the most treasured and expensive example anyone could own and was typically reserved for royalty. To add decorative and intellectual interest to the textiles, weavers incorporated symbols depicting various stories from the Fables of Jean de La Fontaine, published from 1668 to 1694 and largely adapted from Aesop and other early storytellers."}},{"museum_id":"cleveland","language":"en","id":"cma-1949-539","position":78,"title":"Cabinet","category":"Decorative Art and Design","subtitle":null,"artist":"André-Charles Boulle (French, 1642–1732)","facts":[{"label":"Date","value":"c. 1690"},{"label":"Medium","value":"ebony, marquetry in metal and tortoise shell"},{"label":"Accession","value":"1949.539"}],"object_url":"https://clevelandart.org/art/1949.539","image":{"src":"/images/cleveland/cma-1949-539.jpg","sourceUrl":"https://clevelandart.org/art/1949.539","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"Appointed cabinetmaker to King Louis XIV in 1672, André-Charles Boulle became a master of furniture making in France during the late 1600s until his death in 1732. Known primarily for his use of marquetry, in which metal patterns are inlaid into tortoiseshell then applied within the veneered surface of the furniture, Boulle established a level of quality and craftsmanship few others could achieve. As a result, his work found favor at the royal court and among other aristocrats and diplomats eager to impress the king. The inclusion of a medallion depicting Louis XIV within the bronze decoration of this chest would have identified the owner with the royal court. Often exhibiting stout architectural proportions with elegant groups of inlaid motifs such as the parrot on the central panel of this chest, Boulle’s designs are an example of the intellectual fashion for contrasting ideas, materials, and motifs."}},{"museum_id":"cleveland","language":"en","id":"cma-1953-363","position":79,"title":"Ewer","category":"Decorative Art and Design","subtitle":null,"artist":"Saint-Porchaire (French)","facts":[{"label":"Date","value":"c. 1540–67"},{"label":"Medium","value":"lead-glazed, white-paste earthenware with inlaid slip decoration"},{"label":"Accession","value":"1953.363"}],"object_url":"https://clevelandart.org/art/1953.363","image":{"src":"/images/cleveland/cma-1953-363.jpg","sourceUrl":"https://clevelandart.org/art/1953.363","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"An example of one of the most extravagant wares of this kind, this ewer is decorated with applied masks and frogs as well as a variety of stamped and inlaid designs. The shape and patterns reflect the metalwork of the time—the final period of this artistic pottery."}},{"museum_id":"cleveland","language":"en","id":"cma-1963-673","position":80,"title":"Imperial Red Cross Easter Egg","category":"Decorative Art and Design","subtitle":null,"artist":"Peter Carl Fabergé (Russian, 1846–1920) · Henrik Wigström (Russian, 1862–1923)","facts":[{"label":"Date","value":"1915"},{"label":"Medium","value":"gold, silver gilt, enamel, glass, ivory"},{"label":"Accession","value":"1963.673"}],"object_url":"https://clevelandart.org/art/1963.673","image":{"src":"/images/cleveland/cma-1963-673.jpg","sourceUrl":"https://clevelandart.org/art/1963.673","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"The House of Fabergé made two imperial Easter eggs in 1915 that honored the contributions of Tsarina Alexandra and her two eldest daughters, Olga and Tatiana, to the war effort as Red Cross Sisters of Mercy. Compared to other Fabergé eggs elaborately ornamented with jewels, the eggs reflected the mood of austerity in Russia during World War I. This version becomes an icon when opened, revealing miniatures of the patron saints of the tsarina’s daughters. After the Russian Revolution, this relic of the Tsarist past was sold by the Soviet government to raise needed cash for the treasury."}},{"museum_id":"cleveland","language":"en","id":"cma-1966-432","position":81,"title":"Hinds House Window","category":"Decorative Art and Design","subtitle":null,"artist":"Tiffany Glass & Decorating Company (America, New York, 1892–1902)","facts":[{"label":"Date","value":"c. 1900"},{"label":"Medium","value":"leaded glass"},{"label":"Accession","value":"1966.432"}],"object_url":"https://clevelandart.org/art/1966.432","image":{"src":"/images/cleveland/cma-1966-432.jpg","sourceUrl":"https://clevelandart.org/art/1966.432","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"In this window commissioned for the Howell Hinds house around 1900, thousands of richly colored glass pieces have been arranged and layered to paint an idyllic three-dimensional scene that would have warmly glowed in the afternoon sunlight. Located at 2200 Overlook Road in Cleveland, Ohio, the house was demolished in 1930 in a similar fate as other nearby estates. Photographs show the placement of the window in the drawing room next to the fireplace as well as the opulent interiors Louis Comfort Tiffany designed for the library and dining room."}},{"museum_id":"cleveland","language":"en","id":"cma-1977-182","position":82,"title":"Covered Tureen on Stand (Pot-à-oille)","category":"Decorative Art and Design","subtitle":null,"artist":"Juste-Aurèle Meissonnier (French, 1695–1750) · Pierre-François Bonnestrenne (French)","facts":[{"label":"Date","value":"1735–38"},{"label":"Medium","value":"silver"},{"label":"Accession","value":"1977.182"}],"object_url":"https://clevelandart.org/art/1977.182","image":{"src":"/images/cleveland/cma-1977-182.jpg","sourceUrl":"https://clevelandart.org/art/1977.182","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"Juste-Aurèle Meissonnier transformed the traditional covered tureen into an imaginative shell form. The vegetables and animals on the cover refer to the stew’s ingredients, or oille, served from this vessel. Weighing nearly 44 pounds (20 kilograms), the tureen presents a dazzling display of wealth. It was commissioned by the English Duke of Kingston, as one of a pair. The tureens are among the most celebrated surviving examples of 1700s French silver, representing the defining objects of the Rococo—a style characterized by asymmetrical, curving forms, and motifs inspired by nature. Meissonnier collaborated with two master silversmiths on this tureen but asserted his authorship through a prominent inscription on the stand, reading: “Made by J. A. Meissonnier, Architect.” Identifying himself as an architect rather than a goldsmith reflects his ambition to elevate his status beyond his artisanal background."}},{"museum_id":"cleveland","language":"en","id":"cma-1984-58","position":83,"title":"Hen and Chicks Covered Tureen on Stand","category":"Decorative Art and Design","subtitle":null,"artist":"Chelsea Porcelain Factory (Britain, London, 1745–84)","facts":[{"label":"Date","value":"c. 1755"},{"label":"Medium","value":"soft-paste porcelain"},{"label":"Accession","value":"1984.58"}],"object_url":"https://clevelandart.org/art/1984.58","image":{"src":"/images/cleveland/cma-1984-58.jpg","sourceUrl":"https://clevelandart.org/art/1984.58","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"The ceramic factory at Chelsea, located along the river Thames in western London, was Britain’s most renowned factory of decorative porcelain in the mid-1700s. Large tureens in the form of chickens or rabbits appealed to wealthy aristocrats, who took great care in developing specimen animal and poultry breeds on their country estates. The design for this particular tureen was taken from a popular seventeenth-century print by Francis Barlow depicting a farmyard."}},{"museum_id":"cleveland","language":"en","id":"cma-1985-72","position":84,"title":"Sideboard","category":"Decorative Art and Design","subtitle":null,"artist":"Joseph Alexis Bailly (American, 1825–1883)","facts":[{"label":"Date","value":"c. 1855"},{"label":"Medium","value":"walnut"},{"label":"Accession","value":"1985.72"}],"object_url":"https://clevelandart.org/art/1985.72","image":{"src":"/images/cleveland/cma-1985-72.jpg","sourceUrl":"https://clevelandart.org/art/1985.72","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"Newly acquired wealth from railroad production, manufacturing, and an expanded economy produced a new elite class of Americans who looked abroad for sources of decoration to adorn their lives. Grand, baronial furniture, reminiscent of German hunting lodges or French castles, became popular during the mid 1800s among America’s wealthy. Elaborate displays of abundance were reflected in the carvings of flora, fauna, and freshly hunted game. The depictions of Native American hunters on this example, most likely made in Philadelphia, may have meant that this piece was displayed at one of the many international expositions that occurred during this period."}},{"museum_id":"cleveland","language":"en","id":"cma-1991-45","position":85,"title":"Tea Table","category":"Decorative Art and Design","subtitle":null,"artist":"Carlo Bugatti (Italian, 1856–1940)","facts":[{"label":"Date","value":"c. 1907"},{"label":"Medium","value":"inlaid wood (mahogany?), cast and gilded bronze mounts, inlays of ivory or bone, metal, and mother-of-pearl (marine mussels or pearl oysters)"},{"label":"Accession","value":"1991.45"}],"object_url":"https://clevelandart.org/art/1991.45","image":{"src":"/images/cleveland/cma-1991-45.jpg","sourceUrl":"https://clevelandart.org/art/1991.45","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"Luxurious materials might catch the eye first, but a closer look reveals the imaginary creatures that adorn the surface of this table. Featuring elaborate arches, a favorite motif that appeared throughout Bugatti's furniture, this fantastical imagery is a window into the designer's expressive imagination."}},{"museum_id":"cleveland","language":"en","id":"cma-1997-58","position":86,"title":"Fire Screen","category":"Decorative Art and Design","subtitle":null,"artist":"Herter Brothers (American)","facts":[{"label":"Date","value":"c. 1878–80"},{"label":"Medium","value":"gilded wood, painted and gilded wood panels, brocaded silk, embossed paper"},{"label":"Accession","value":"1997.58"}],"object_url":"https://clevelandart.org/art/1997.58","image":{"src":"/images/cleveland/cma-1997-58.jpg","sourceUrl":"https://clevelandart.org/art/1997.58","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"During the 1870s the New York firm of Herter Brothers produced some of the most sophisticated and technically refined furniture made anywhere in the world at that date. Although the firm is known to have made a considerable quantity of gilded furniture, this fire screen is one of only a few examples to survive in good condition. The painted and gilded embossed panel of birds and flowers was likely made in Japan."}},{"museum_id":"cleveland","language":"en","id":"cma-2007-180","position":87,"title":"Frogs and Lily Pads (Grenouilles et Nénuphars) Vase","category":"Decorative Art and Design","subtitle":null,"artist":"René Lalique (French, 1860–1945)","facts":[{"label":"Date","value":"1909–12"},{"label":"Medium","value":"glass"},{"label":"Accession","value":"2007.180"}],"object_url":"https://clevelandart.org/art/2007.180","image":{"src":"/images/cleveland/cma-2007-180.jpg","sourceUrl":"https://clevelandart.org/art/2007.180","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"This vase is an early example of French designer René Lalique's experimentation with producing artistic glass. Lalique combines applied, cast, and molded glass techniques to achieve an ethereal effect of a murky swamp, a typical Art Nouveau motif. Lily pads adorn the surface with green frogs perched on top."}},{"museum_id":"cleveland","language":"en","id":"cma-2010-2","position":88,"title":"Pair of Candelabra","category":"Decorative Art and Design","subtitle":null,"artist":null,"facts":[{"label":"Date","value":"c. 1790–95"},{"label":"Medium","value":"cut and polished steel with gold and silvered decoration"},{"label":"Culture","value":"Russia, Tula"},{"label":"Accession","value":"2010.2"}],"object_url":"https://clevelandart.org/art/2010.2","image":{"src":"/images/cleveland/cma-2010-2.jpg","sourceUrl":"https://clevelandart.org/art/2010.2","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"Founded in 1705 by Peter the Great, the armory at Tula developed steadily over the 18th century to become the center of Russian metalworking, especially in arms manufacturing. In the 1770s and 1780s, Catherine the Great took a keen interest in the work produced there, sending several of the most proficient craftsmen to England to study the decorative application of steel in armories in Sheffield and London. Subsequently, the Tula artisans surpassed the metalworkers in Britain and elsewhere in Europe, producing decorative wares that were as precious and precise as their brilliantly embellished firearms. Empress Catherine was so pleased that she commissioned diplomatic and royal gifts of Tula ware as well as several noted examples of furniture in the distinctive Tula style of cut steel, gilt-bronze, silver, and gold. The most recognizable characteristic of Tula ware was the use of beads of steel that replicated faceted diamonds and crystals. No other region was able to achieve the vividness of this technique in cut steel. Most works in Tula steel were small and precious such as inkstands, bobbin holders, buttons, footstools, single candlesticks, etc. These candelabra typify the Neoclassical taste in Russia during the late 1700s, a significant moment in Russian design because of the mature level of craftsmanship and style."}},{"museum_id":"cleveland","language":"en","id":"cma-1914-561","position":89,"title":"Coffin of Bakenmut","category":"Egyptian and Ancient Near Eastern Art","subtitle":null,"artist":null,"facts":[{"label":"Date","value":"c. 1000–900 BCE"},{"label":"Medium","value":"gessoed and painted sycamore fig"},{"label":"Culture","value":"Egypt, Thebes, Third Intermediate (1069–715 BCE), Dynasties 21–22"},{"label":"Accession","value":"1914.561"}],"object_url":"https://clevelandart.org/art/1914.561","image":{"src":"/images/cleveland/cma-1914-561.jpg","sourceUrl":"https://clevelandart.org/art/1914.561","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"The coffin of Bakenmut is one of the finest examples of painted wooden coffins made for the priests of Amen and their families at Thebes during Dynasty 21 and early Dynasty 22. The pharaohs of this time were no longer buried in the Valley of the Kings, but instead built tombs in the Delta, far to the north, where they resided. Security was lax in the Theban necropolis. The coffins and funerary goods of the wealthy citizens of Thebes were placed in unmarked and undecorated family tombs cut into the cliffs on the west bank of the Nile. All the care and detail that in more prosperous times were devoted to the decoration of the tomb chapel were now lavished on the elaborately painted coffins. Every available surface is crowded with religious scenes, images of funerary gods and goddesses, protective spells, and magical symbols. The deceased appears mummiform. An elaborate floral collar entirely covers the upper body, exposing only the separately attached hands (now lost). A pair of red \"mummy braces\" are crossed over the chest, their point of intersection marked by a winged sun disk. The lower body is covered with tiny figures modeled in gesso against a yellow background, which gives the effect of gold inlaid with glass or semiprecious stone. The decoration on the interior features two deified dead kings of Dynasty 18. Although these rulers had lived centuries before, memory of their greatness was still very much alive. The main scene near the top depicts Tuthmosis III, the great military pharaoh, who lived 500 years before Bakenmut. Posed as a mummy, the ruler wears a brilliant feathered garment enfolding him with falcon’s wings. The scene below features back-to-back seated images of Amenhotep I, regarded as the patron of the Theban cemetery and worshiped as a local god there."}},{"museum_id":"cleveland","language":"en","id":"cma-1914-714","position":90,"title":"Coffin of Nesykhonsu","category":"Egyptian and Ancient Near Eastern Art","subtitle":null,"artist":null,"facts":[{"label":"Date","value":"c. 976–889 BCE"},{"label":"Medium","value":"gessoed and painted sycamore fig"},{"label":"Culture","value":"Egypt, Thebes, Third Intermediate (1069–715 BCE), Dynasties 21–22"},{"label":"Accession","value":"1914.714"}],"object_url":"https://clevelandart.org/art/1914.714","image":{"src":"/images/cleveland/cma-1914-714.jpg","sourceUrl":"https://clevelandart.org/art/1914.714","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"Egyptian coffins told stories and illustrated spells to help the deceased transition safely to the afterlife. Inside Nesykhonsu's coffin there are two jackals, one facing right and the other left, near the top. Here, the jackal represents the powerful deity Anubis, the god of the afterlife and embalming."}},{"museum_id":"cleveland","language":"en","id":"cma-1920-1975","position":91,"title":"Trial Piece Worked on Both Sides","category":"Egyptian and Ancient Near Eastern Art","subtitle":null,"artist":null,"facts":[{"label":"Date","value":"c. 1391–1353 BCE"},{"label":"Medium","value":"limestone"},{"label":"Culture","value":"Egypt, probably Thebes, New Kingdom (1540–1069 BCE), Dynasty 18, reign of Amenhotep III (1390–1352 BCE)"},{"label":"Accession","value":"1920.1975"}],"object_url":"https://clevelandart.org/art/1920.1975","image":{"src":"/images/cleveland/cma-1920-1975.jpg","sourceUrl":"https://clevelandart.org/art/1920.1975","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"This carved flake of limestone provides a fascinating glimpse of the ancient artist at work. One side, by far the better, features four studies of heads. At the upper left is an Asiatic. He has a low forehead, a prominent nose, and a long, pointed beard. To his right is a Nubian wearing the short, round headdress and large loop earring that the Egyptians usually identified with this ethnic group. The bottom row presents images from within Egypt. At the left is a stock image of a king. To his right is another Egyptian, whose clean-shaven head immediately identifies him as a priest. The rather routine, basic subjects of the other side show a far lower level of accomplishment. The sole details of any skill are the incomplete head of the god Bes at the bottom center and the human ear at the left edge. The simple neb-signs (baskets) are poorly executed, and the drawing of the hand is embarrassingly bad. At the lower right is a thickly banded human eye. Above that is the fair head of a princess wearing a short wig, wide headband, and thick sidelock. At the upper left are the beginnings (or the remains) of the bewigged head of a courtier, the face mostly obliterated."}},{"museum_id":"cleveland","language":"en","id":"cma-1943-246","position":92,"title":"Saluting Protective Spirit","category":"Egyptian and Ancient Near Eastern Art","subtitle":null,"artist":null,"facts":[{"label":"Date","value":"883–859 BCE"},{"label":"Medium","value":"gypsum"},{"label":"Culture","value":"Neo-Assyrian (911–609 BCE), Iraq, Nimrud, Northwest Palace, reign of Ashurnasirpal II (883–859 BCE)"},{"label":"Accession","value":"1943.246"}],"object_url":"https://clevelandart.org/art/1943.246","image":{"src":"/images/cleveland/cma-1943-246.jpg","sourceUrl":"https://clevelandart.org/art/1943.246","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"Striding forward with muscular arms and legs, this winged deity offers a gesture of salutation along with symbols of agricultural bounty. Inscribed with an account of the Assyrian king Ashurnasirpal II's military conquests and victories, this relief once stood alongside hundreds of similar ones that decorated the palace at Nimrud."}},{"museum_id":"cleveland","language":"en","id":"cma-1948-141","position":93,"title":"Torso of Amenpayom","category":"Egyptian and Ancient Near Eastern Art","subtitle":null,"artist":null,"facts":[{"label":"Date","value":"probably 200–100 BCE"},{"label":"Medium","value":"granodiorite"},{"label":"Culture","value":"Egypt, Greco-Roman period (332 BCE–395 CE), Ptolemaic dynasty (305–30 BCE)"},{"label":"Accession","value":"1948.141"}],"object_url":"https://clevelandart.org/art/1948.141","image":{"src":"/images/cleveland/cma-1948-141.jpg","sourceUrl":"https://clevelandart.org/art/1948.141","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"This magnificent life-sized torso is inscribed for Amenpayom, the great army general of the district of Mendes in the Nile Delta. By the end of the Ptolemaic dynasty (305-30 BC) when this statue was made, the Egyptians could draw on 3,000 years of expertise carving hard stone. Enough remains to show that Amenpayom was represented in the traditional pose for men: left leg striding forward, arms at his sides, and supported by a back pillar. The subtle, masterful treatment of the undulating musculature and meticulous, flawless polish are hallmarks of this period, when Egyptian artists reveled in the natural beauty of the human form."}},{"museum_id":"cleveland","language":"en","id":"cma-1952-513","position":94,"title":"Head of Amenhotep III Wearing the Blue Crown","category":"Egyptian and Ancient Near Eastern Art","subtitle":null,"artist":null,"facts":[{"label":"Date","value":"c. 1391–1353 BCE"},{"label":"Medium","value":"granodiorite"},{"label":"Culture","value":"Egypt, New Kingdom (1540–1069 BCE), Dynasty 18, reign of Amenhotep III (1390–1352 BCE)"},{"label":"Accession","value":"1952.513"}],"object_url":"https://clevelandart.org/art/1952.513","image":{"src":"/images/cleveland/cma-1952-513.jpg","sourceUrl":"https://clevelandart.org/art/1952.513","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"During the long, peaceful reign of Amenhotep III, Egypt reached a pinnacle of wealth and splendor. This magnificent portrait captures the ruler's exotic features to perfection. He has large, almond-shaped eyes, elegant arched eyebrows, and a full mouth. His face is youthful and without blemish. The bone structure is lost in the fleshy fullness of the face. The contrast between polished and roughened surfaces is a hallmark of hard stone images of Amenhotep III. The flesh areas were smoothed to a glistening sheen, while the eyeballs and the crown were left rougher. The roughening of the crown also had a practical purpose, for the upper portion was originally painted blue and the browband was painted yellow. The paint would have adhered better to the unpolished surface."}},{"museum_id":"cleveland","language":"en","id":"cma-1960-56","position":95,"title":"Statue of Amenemhat III","category":"Egyptian and Ancient Near Eastern Art","subtitle":null,"artist":null,"facts":[{"label":"Date","value":"c. 1859–1814 BCE"},{"label":"Medium","value":"granodiorite"},{"label":"Culture","value":"Egypt, Middle Kingdom (2040–1648 BCE), Dynasty 12, reign of Amenemhat III (1860–1814 BCE)"},{"label":"Accession","value":"1960.56"}],"object_url":"https://clevelandart.org/art/1960.56","image":{"src":"/images/cleveland/cma-1960-56.jpg","sourceUrl":"https://clevelandart.org/art/1960.56","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"Even though this statue of a king is uninscribed, its distinctive features identify it without any doubt as a portrait of Amenemhat III. The heavy brows, prominent cheekbones, hollow cheeks, jutting lower jaw, and tightly bunched muscles at the corners of the mouth make a strikingly realistic impression. Not realistic, however, are the king’s supersized ears. Instead, they symbolize the ruler’s willingness to hear the prayers of his people. If this image had been carved in relief, the king’s hands would have been uplifted in worship. Here, however, to prevent the breakage of projecting limbs, the ruler’s hands are pressed flat against the front his kilt, a portion of which is looped over his belt."}},{"museum_id":"cleveland","language":"en","id":"cma-1961-205","position":96,"title":"Nome Gods Bearing Offerings","category":"Egyptian and Ancient Near Eastern Art","subtitle":null,"artist":null,"facts":[{"label":"Date","value":"c. 1391–1353 BCE"},{"label":"Medium","value":"painted limestone"},{"label":"Culture","value":"Egypt, New Kingdom (1540–1069 BCE), Dynasty 18, reign of Amenhotep III (1390–1352 BCE)"},{"label":"Accession","value":"1961.205"}],"object_url":"https://clevelandart.org/art/1961.205","image":{"src":"/images/cleveland/cma-1961-205.jpg","sourceUrl":"https://clevelandart.org/art/1961.205","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"These blocks from a temple wall show four figures identified as nomes, or provinces, of ancient Egypt. Carrying trays heaped with offerings and leading sacrificial animals, they personify the bounty of the land that they bring to the god who stood in the upper register, facing a figure of the king, Amenhotep III. These blocks may be from Amenhotep III's temple, dedicated to the god Horus."}},{"museum_id":"cleveland","language":"en","id":"cma-1961-417","position":97,"title":"Head of Amenhotep III Wearing the Round Wig","category":"Egyptian and Ancient Near Eastern Art","subtitle":null,"artist":null,"facts":[{"label":"Date","value":"c. 1391–1353 BCE"},{"label":"Medium","value":"brown quartzite"},{"label":"Culture","value":"Egypt, New Kingdom (1540–1069 BCE), Dynasty 18, reign of Amenhotep III (1390–1352 BCE)"},{"label":"Accession","value":"1961.417"}],"object_url":"https://clevelandart.org/art/1961.417","image":{"src":"/images/cleveland/cma-1961-417.jpg","sourceUrl":"https://clevelandart.org/art/1961.417","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"Although he must have been nearly 50 years old when this portrait was carved, Amenhotep III appears more youthful than ever. Over a round, curly wig he wears a diadem with side streamers adorned with cobras bearing sun disks on their heads. The stone quartzite was associated with the sun on account of its ruddy hues, ranging in color from brown to red to purple. It was a favorite of Amenhotep III, the king who called himself the \"dazzling sun-disk of all lands.\""}},{"museum_id":"cleveland","language":"en","id":"cma-1971-45","position":98,"title":"Priest-King or Deity","category":"Egyptian and Ancient Near Eastern Art","subtitle":null,"artist":null,"facts":[{"label":"Date","value":"c. 1600 BCE"},{"label":"Medium","value":"basalt with bone eyes (left, ancient; right, restored)"},{"label":"Culture","value":"Hittite, North Syria"},{"label":"Accession","value":"1971.45"}],"object_url":"https://clevelandart.org/art/1971.45","image":{"src":"/images/cleveland/cma-1971-45.jpg","sourceUrl":"https://clevelandart.org/art/1971.45","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"The Hittites migrated into Anatolia in the 3rd millennium BCE and spoke an Indo-European language, a group that includes Greek, Latin, Persian, Sanskrit, English, and most modern European languages. They were the first ancient people to use iron for weapons. From about 1600–1200 BCE their empire was at its peak, extending from central Anatolia to Syria, and south along the eastern Mediterranean. Their vast empire and interest in commerce enabled the Hittites to spread Mesopotamian ideas and culture throughout the ancient Mediterranean world. This large basalt sculpture is exceptionally rare in depicting a Hittite god or priest-king wearing a horned conical crown, false beard, and long robe. He holds a bowl in his right hand and once held something in his left, perhaps a staff or sword."}},{"museum_id":"cleveland","language":"en","id":"cma-1971-137","position":99,"title":"Funerary Portrait of a Young Girl","category":"Egyptian and Ancient Near Eastern Art","subtitle":null,"artist":null,"facts":[{"label":"Date","value":"c. 25–37 CE"},{"label":"Medium","value":"encaustic on linden wood"},{"label":"Culture","value":"Egypt, Roman Empire, late Tiberian"},{"label":"Accession","value":"1971.137"}],"object_url":"https://clevelandart.org/art/1971.137","image":{"src":"/images/cleveland/cma-1971-137.jpg","sourceUrl":"https://clevelandart.org/art/1971.137","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"Transforming the spirit—not beautifying the mortal body—may have been the purpose of adding golden lips and jewelry to this painting. Egyptian-style burial customs and arts persisted throughout Greek, Roman, and Byzantine rule over Egypt (305 BCE–641 CE). The woman depicted in this panel lived between cultures. Her or her family’s choice of mummification reflected historical Egyptian practices of creating a physical “duplicate” for the deceased’s soul to rest in, and their decision to color her lips gold here may symbolize how death transformed her into an akh (effective spirit). In contrast, the choice of her clothing and hairstyle showed her embrace of contemporary ideals of Hellenic (Greco-Roman) Egyptian identity."}},{"museum_id":"cleveland","language":"en","id":"cma-1928-856","position":100,"title":"Sarcophagus","category":"Greek and Roman Art","subtitle":null,"artist":null,"facts":[{"label":"Date","value":"c. 100–125 CE"},{"label":"Medium","value":"Greek marble"},{"label":"Culture","value":"Italy, Rome, Roman Empire"},{"label":"Accession","value":"1928.856"}],"object_url":"https://clevelandart.org/art/1928.856","image":{"src":"/images/cleveland/cma-1928-856.jpg","sourceUrl":"https://clevelandart.org/art/1928.856","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"The tragic figure Orestes appears three times on the front of this sarcophagus, always wielding a short sword. In the center he stands over the body of his mother Clytemnestra, and at center left over the body of her lover Aegisthus. Orestes has killed them both to avenge their murder of his father Agamemnon, upon his return from years of fighting at Troy. At the far left, three Furies (avenging spirits) rest upon Agamemnon's tomb, while at the far right, Orestes atones for the murders at the Delphian shrine of Apollo, marked by a tripod and rock. On the lid, four reclining women symbolize the seasons, arranged in right-to-left order: Winter, Spring, Summer, Autumn, as indicated by their dress and the contents of their baskets."}},{"museum_id":"cleveland","language":"en","id":"cma-1945-13","position":101,"title":"Sleep and Death Cista Handle","category":"Greek and Roman Art","subtitle":null,"artist":null,"facts":[{"label":"Date","value":"400–375 BCE"},{"label":"Medium","value":"bronze"},{"label":"Culture","value":"Etruscan"},{"label":"Accession","value":"1945.13"}],"object_url":"https://clevelandart.org/art/1945.13","image":{"src":"/images/cleveland/cma-1945-13.jpg","sourceUrl":"https://clevelandart.org/art/1945.13","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"Designed for attachment to the lid of a large bronze cista, a cylindrical lidded box, these three figures probably represent Sleep (Hypnos) and Death (Thanatos) holding the body of Sarpedon. A son of Zeus who helped to defend Troy from invading Greek forces, \"godlike Sarpedon of the brazen helmet\" fell at the hands of Patroclus, as told by Homer in Book XVI of the Iliad. Apollo then intervened to protect the body, removing it from danger and entrusting it to the two winged deities, as depicted here and in a number of other ancient artworks, Greek and Etruscan alike. If not Sarpedon, the fallen warrior could be Memnon, the son of Eos and Tithonos slain by Achilles."}},{"museum_id":"cleveland","language":"en","id":"cma-1953-124","position":102,"title":"Candelabrum Stand of a Dancing Maenad","category":"Greek and Roman Art","subtitle":null,"artist":null,"facts":[{"label":"Date","value":"525–500 BCE"},{"label":"Medium","value":"bronze"},{"label":"Culture","value":"Etruscan"},{"label":"Accession","value":"1953.124"}],"object_url":"https://clevelandart.org/art/1953.124","image":{"src":"/images/cleveland/cma-1953-124.jpg","sourceUrl":"https://clevelandart.org/art/1953.124","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"Conceived primarily in two dimensions—front and rear silhouette—this small bronze dancer probably once belonged to an elaborate candelabra or incense burner. The exaggeratedly long fingers and pointed shoes characterize the work as Etruscan, as do the stylized folds of the figure’s dress, which add visual interest but not verisimilitude. While her right hand holds above her head a cylindrical support, her left squeezes a small object, perhaps a fruit or clapper."}},{"museum_id":"cleveland","language":"en","id":"cma-1953-125","position":103,"title":"Torso of a Kouros","category":"Greek and Roman Art","subtitle":null,"artist":null,"facts":[{"label":"Date","value":"c. 550 BCE"},{"label":"Medium","value":"marble"},{"label":"Culture","value":"Greece, Archaic period"},{"label":"Accession","value":"1953.125"}],"object_url":"https://clevelandart.org/art/1953.125","image":{"src":"/images/cleveland/cma-1953-125.jpg","sourceUrl":"https://clevelandart.org/art/1953.125","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"Known as a kouros, the ancient Greek word for a youth, this fragmentary statue belongs to a relatively rare type of large-scale stone sculpture made for little more than a century—shortly before 600 BCE to soon after 500 BCE. A nude youth standing with arms to the sides and one foot slightly advanced, the type probably originated under Egyptian influence, but then developed along entirely Greek lines. Found in sanctuaries as well as cemeteries across the ancient Greek world, kouroi may represent gods—especially Apollo—as well as mortals. Although incomplete, this kouros retains much of its beautifully finished and patterned surface."}},{"museum_id":"cleveland","language":"en","id":"cma-1966-114","position":104,"title":"White-Ground Lekythos (Oil Vessel): Atalanta and Erotes","category":"Greek and Roman Art","subtitle":null,"artist":"Douris (Greek, Attic, active c. 500–470 BCE)","facts":[{"label":"Date","value":"c. 500–490 BCE"},{"label":"Medium","value":"ceramic"},{"label":"Accession","value":"1966.114"}],"object_url":"https://clevelandart.org/art/1966.114","image":{"src":"/images/cleveland/cma-1966-114.jpg","sourceUrl":"https://clevelandart.org/art/1966.114","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"Known as \"white-ground\" because of the white clay slip applied as a surface for figural decoration, vases of this type give some idea of the appearance of lost ancient large-scale wall paintings. Both remarkably well preserved and masterfully composed, the images cover the entire circumference of the vase. At the center, Atalanta, the virgin huntress renowned for both her speed and her opposition to marriage, races to the right while looking back at Eros, the winged god of love; both figures are named. This Eros, bounding forward, tries to crown her, while two additional Erotes (also named) further hem her in. Love will win."}},{"museum_id":"cleveland","language":"en","id":"cma-1966-371","position":105,"title":"The Vicarello Goblet","category":"Greek and Roman Art","subtitle":null,"artist":null,"facts":[{"label":"Date","value":"25 BCE–25 CE"},{"label":"Medium","value":"silver"},{"label":"Culture","value":"Italy, Vicarello (ancient Aquae Apollinares), Roman, Augustan period"},{"label":"Accession","value":"1966.371"}],"object_url":"https://clevelandart.org/art/1966.371","image":{"src":"/images/cleveland/cma-1966-371.jpg","sourceUrl":"https://clevelandart.org/art/1966.371","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"This masterpiece of the Roman silversmith’s art is exquisitely worked in relief. The multifigure scene centers on a rustic shrine of the ithyphallic fertility god Priapus, son of Dionysos. He takes the form of a stylized boundary marker atop a column, where a woman seems to have brought him to life by touching him. To the left sits a table with votive offerings to the god. Flanking the shrine are a satyr and maenad, dancing ecstatically."}},{"museum_id":"cleveland","language":"en","id":"cma-1971-46","position":106,"title":"Black-Figure Dinos (Mixing Vessel): Warships (Int.); Heroic Scenes (Top)","category":"Greek and Roman Art","subtitle":null,"artist":"Antimenes Painter (Greek, Attic, active c. 530–510 BCE)","facts":[{"label":"Date","value":"c. 520–515 BCE"},{"label":"Medium","value":"ceramic"},{"label":"Accession","value":"1971.46"}],"object_url":"https://clevelandart.org/art/1971.46","image":{"src":"/images/cleveland/cma-1971-46.jpg","sourceUrl":"https://clevelandart.org/art/1971.46","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"Designed for use at a symposium, or drinking party, this large dinos has a wide mouth allowing easy access to its contents—wine mixed with water (and sometimes other ingredients for flavoring). While drinking, symposiasts would often recite poetry and celebrate the mythological exploits of gods and heroes, perhaps prompted by the images painted on their pottery. Here, the vase-painter clearly anticipated such use; when the vessel was full, the ships painted on the inside of the rim would appear to sail across the “wine-dark sea” (to borrow a phrase found frequently in Homer’s Iliad and Odyssey). Other heroic scenes, including Herakles wrestling the Nemean lion and Theseus battling the Minotaur, appear on top of the rim, interspersed with chariots and anonymous combats."}},{"museum_id":"cleveland","language":"en","id":"cma-1975-1","position":107,"title":"Black-Figure Hydria (Water Vessel): Frontal Quadriga (Body); Theseus and Minotaur (Shoulder)","category":"Greek and Roman Art","subtitle":null,"artist":"Antimenes Painter (Greek, Attic, active c. 530–510 BCE)","facts":[{"label":"Date","value":"c. 520 BCE"},{"label":"Medium","value":"ceramic"},{"label":"Accession","value":"1975.1"}],"object_url":"https://clevelandart.org/art/1975.1","image":{"src":"/images/cleveland/cma-1975-1.jpg","sourceUrl":"https://clevelandart.org/art/1975.1","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"Although their subjects differ, the three fields of figured decoration on this vessel relate to one another metaphorically through the theme of victory. Just as Theseus defeats the Minotaur on the shoulder, two lions converge on a deer in the predella (the small, lowermost panel). In the largest panel, victory is still to come, presumably for all three warriors shown: one in the chariot behind his driver, and one on foot on either side. Somewhat unusually, two of the warriors look directly out at the viewer, their frontal faces an interesting complement to the much more common frontal chariot."}},{"museum_id":"cleveland","language":"en","id":"cma-1978-59","position":108,"title":"Red-Figure Lekythos (Oil Vessel): Athena Slaying Giant (body); Satyr between Maenads (shoulder)","category":"Greek and Roman Art","subtitle":null,"artist":"Berlin Painter (Greek, Attic, active c. 505–460 BC) · Painter of Goluchow 37 (Greek, Attic, active c. 490–460 BC)","facts":[{"label":"Date","value":"c. 490 BCE"},{"label":"Medium","value":"ceramic"},{"label":"Accession","value":"1978.59"}],"object_url":"https://clevelandart.org/art/1978.59","image":{"src":"/images/cleveland/cma-1978-59.jpg","sourceUrl":"https://clevelandart.org/art/1978.59","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"The two separate areas of figural decoration on this vase have been attributed to different painters: the small satyr and maenads on the shoulder to the Berlin Painter; and the larger figures of Athena and the slain Giant Enkelados on the body to the Painter of Goluchow 37. Scholars have named these two painters, whose actual names remain unknown, after other vases they have painted, now in Berlin and Warsaw. The victory of Athena and the Olympian gods over the Giants has been interpreted as a metaphor for the Greek victory over the Persians around the time this vase was made. Thus, although Enkelados appears as a fully armed warrior, he falls in utter and complete defeat—bleeding from multiple wounds, eyes rolling back, sword dropping from his hand."}},{"museum_id":"cleveland","language":"en","id":"cma-1985-50","position":109,"title":"Red-Figure Fish Plate: Octopi, Mullet, Bream, Shellfish","category":"Greek and Roman Art","subtitle":null,"artist":"Asteas/Python Workshop (South Italian, Paestan, active c. 360–320 BCE)","facts":[{"label":"Date","value":"c. 340–330 BCE"},{"label":"Medium","value":"ceramic"},{"label":"Accession","value":"1985.50"}],"object_url":"https://clevelandart.org/art/1985.50","image":{"src":"/images/cleveland/cma-1985-50.jpg","sourceUrl":"https://clevelandart.org/art/1985.50","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"Although first developed in Athens, red-figure fish plates became especially popular in South Italy and Sicily in the 300s BC. All feature a short foot and a small central depression, but those produced in the workshop of Asteas and Python, like this one, are the largest and most ornate. Archaeologists have closely studied the fish and other sea creatures represented, identifying many of them with species still found (and eaten) in the Mediterranean; included here are octopi, mullet, bream, and various shellfish."}},{"museum_id":"cleveland","language":"en","id":"cma-1991-1","position":110,"title":"Red-Figure Calyx-Krater (Mixing Vessel): Medea in Chariot (A); Telephos with Baby Orestes (B)","category":"Greek and Roman Art","subtitle":null,"artist":"Policoro Painter (South Italian, Lucanian, active c. 400 BCE)","facts":[{"label":"Date","value":"c. 400 BCE"},{"label":"Medium","value":"ceramic"},{"label":"Accession","value":"1991.1"}],"object_url":"https://clevelandart.org/art/1991.1","image":{"src":"/images/cleveland/cma-1991-1.jpg","sourceUrl":"https://clevelandart.org/art/1991.1","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"The remarkable scene on the front of this vase relates to the famous tragedy Medea, written by Euripides and first produced in Athens in 431 BC. Framed in the center by a halo (recalling her sun god grandfather Helios), the sorceress Medea flies off in a dragon-drawn chariot. Seeking revenge against her husband Jason, leader of the Argonauts, Medea has just slain their two children. Two Furies flank her, while Jason and a distraught nurse and teacher approach the bodies on the altar below. A different tragedy unfolds on the other side of the vase, from Euripides’s Telephos (438 BC). The wounded warrior Telephos holds the baby Orestes hostage at an altar, with Agamemnon and Clytemnestra rushing to save their son."}},{"museum_id":"cleveland","language":"en","id":"cma-1924-859","position":111,"title":"Table Fountain","category":"Medieval Art","subtitle":null,"artist":null,"facts":[{"label":"Date","value":"c. 1320–40"},{"label":"Medium","value":"gilt-silver and translucent enamels"},{"label":"Culture","value":"France, Paris"},{"label":"Accession","value":"1924.859"}],"object_url":"https://clevelandart.org/art/1924.859","image":{"src":"/images/cleveland/cma-1924-859.jpg","sourceUrl":"https://clevelandart.org/art/1924.859","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"Conceptually and stylistically, this object is beyond all else a piece of Gothic architecture in miniature with vaults, pinnacles, columns, and traceried arches. Though the artist who created it is unknown, he was unquestionably inspired by the great Gothic buildings of his time. The table fountain is a three-tiered assembly combining cast elements with bent sheets of gilt-silver. To these have been attached a series of enamel plaques representing grotesque figures, some of which play musical instruments. Water wheels and bells were added to capture motion and sound. The rich detail, precious materials, and involved ornamentation of this deluxe object suggest it would have been expensive to produce and highly treasured by its original owner, someone of high status, and would have been deployed as an object of spectacle. This is the most complete example of its type known to survive from the Middle Ages. Medieval inventories reveal that small fountains like this, often taking various forms, and generally made from precious metals, once existed in large numbers, thus making the Cleveland table fountain an extremely rare object."}},{"museum_id":"cleveland","language":"en","id":"cma-1925-1293","position":112,"title":"Ivory Plaque with Enthroned Mother of God (\"The Stroganoff Ivory\")","category":"Medieval Art","subtitle":null,"artist":null,"facts":[{"label":"Date","value":"950–1025"},{"label":"Medium","value":"ivory"},{"label":"Culture","value":"Byzantium, Constantinople, Byzantine period"},{"label":"Accession","value":"1925.1293"}],"object_url":"https://clevelandart.org/art/1925.1293","image":{"src":"/images/cleveland/cma-1925-1293.jpg","sourceUrl":"https://clevelandart.org/art/1925.1293","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"The Mother of God is seated on a lavishly carved, high-backed throne. Two angels hover above, drawing attention to the Christ child poised in her lap. Representations of the enthroned Virgin and Child have a long tradition in Byzantine art, stretching back as far as the 6th century. With one hand raised in blessing, the other holding a scroll, Christ is portrayed here as an emotionless and supernatural child, visualizing for the pious beholder the mystery of his incarnation."}},{"museum_id":"cleveland","language":"en","id":"cma-1931-55","position":113,"title":"Ceremonial Cross of Countess Gertrude","category":"Medieval Art","subtitle":null,"artist":null,"facts":[{"label":"Date","value":"1038 or shortly after"},{"label":"Medium","value":"gold: worked in repoussé; cloisonné enamel, intaglio gems, pearls, wood core"},{"label":"Culture","value":"Germany, Lower Saxony?, 11th century"},{"label":"Accession","value":"1931.55"}],"object_url":"https://clevelandart.org/art/1931.55","image":{"src":"/images/cleveland/cma-1931-55.jpg","sourceUrl":"https://clevelandart.org/art/1931.55","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"This precious gold cross was commissioned by Countess Gertrude (died 1077) and given to the church of Saint Blaise following the death of her husband, Count Liudolf of Brunswick (died 1038). The cross was intended to be carried in liturgical processions or to be placed on a church altar. The inclusion of relics within the crosses endowed them with an additional role as devotional objects. At the center of the four cross arms, fine but much damaged cloisonné enamel plaques represent the symbols of the four Evangelists--an eagle for Saint John (above); a lion for Saint Mark (on the left); an ox for Saint Luke (on the right); and an angel for Saint Matthew (below). Pearls and precious and semiprecious stones are set within an intricate network of gold filigree while a large sapphire, inscribed in a circle and likewise surrounded by pearls and precious stones, is placed at the crossing."}},{"museum_id":"cleveland","language":"en","id":"cma-1932-227","position":114,"title":"The Holy Family with Saint John the Baptist and Saint Margaret","category":"Medieval Art","subtitle":null,"artist":"Filippino Lippi (Italian, c. 1457–1504)","facts":[{"label":"Date","value":"c. 1488–93"},{"label":"Medium","value":"tempera and oil on wood"},{"label":"Accession","value":"1932.227"}],"object_url":"https://clevelandart.org/art/1932.227","image":{"src":"/images/cleveland/cma-1932-227.jpg","sourceUrl":"https://clevelandart.org/art/1932.227","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"This monumental tondo, among Filippino’s most significant works, was commissioned by Neapolitan cardinal Oliviero Carafa, a leading political and ecclesiastical figure. The painter’s ingenious composition harmoniously overlaps five brilliantly colored divine figures within the challenging circular format. Behind a low wall adorned with sacred and domestic objects, Joseph observes the intertwined group of Mary holding Christ, who embraces his cousin John the Baptist, supported by Saint Margaret. Created during Filippino’s Roman years (1488–93), the painting reflects the inspiration he drew from ancient art. The preparatory drawing reveals how he reimagined Greco-Roman figures—his sketch of an antique Venus statue was refashioned into Saint Margaret—while the weathered pier references remnants of ancient architectural and decorative motifs, illustrating Filippino’s deep engagement with the fragments of antique murals, sculpture, and architecture throughout the city."}},{"museum_id":"cleveland","language":"en","id":"cma-1940-129","position":115,"title":"Mourner from the Tomb of John the Fearless and Margaret of Bavaria","category":"Medieval Art","subtitle":null,"artist":"Jean de la Huerta (Spanish, active Burgundy, 1431–62)","facts":[{"label":"Date","value":"1443–45"},{"label":"Medium","value":"salins alabaster"},{"label":"Accession","value":"1940.129"}],"object_url":"https://clevelandart.org/art/1940.129","image":{"src":"/images/cleveland/cma-1940-129.jpg","sourceUrl":"https://clevelandart.org/art/1940.129","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"This monklike figure has a variously textured monochrome surface. Alabaster’s softness made it easy to carve details like the fabric and fur of the mourner’s robe and the codex pages in his hand. This is one of 40 mourners from an elaborate funeral procession beneath an intricately carved alabaster arcade. This mourner comes from the monastery of Champmol near Dijon, which became a primary burial place for Burgundian dukes. The sculpture was part of the tomb of John the Fearless (1371–1419), commissioned by his son Philip the Good (1396–1467), modeled after the earlier monument for Philip the Bold."}},{"museum_id":"cleveland","language":"en","id":"cma-1946-82","position":116,"title":"Saint Jerome and the Lion (From the former Church of St. Peter in Erfurt)","category":"Medieval Art","subtitle":null,"artist":"Tilman Riemenschneider (German, active Würzburg, c. 1460–1531)","facts":[{"label":"Date","value":"c. 1495"},{"label":"Medium","value":"alabaster, traces of polychromy"},{"label":"Accession","value":"1946.82"}],"object_url":"https://clevelandart.org/art/1946.82","image":{"src":"/images/cleveland/cma-1946-82.jpg","sourceUrl":"https://clevelandart.org/art/1946.82","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"This statue shows an important moment from a story about Saint Jerome. One day Jerome encountered a hurt lion. He removed a thorn from its paw, and the grateful animal became Jerome’s lifelong companion. This sculpture is made of alabaster, a soft stone suited for carving fine detail. Look closely! You can see flecks of paint and gold from when it was originally painted. Conservators looked at this sculpture under a microscope and found that the lion once had a red mouth, yellow fur, and black claws."}},{"museum_id":"cleveland","language":"en","id":"cma-1958-66","position":117,"title":"Mourner from the Tomb of Philip the Bold, Duke of Burgundy (1364–1404)","category":"Medieval Art","subtitle":null,"artist":"Claus de Werve (Netherlandish, 1380–1439)","facts":[{"label":"Date","value":"1404–10"},{"label":"Medium","value":"vizille alabaster"},{"label":"Accession","value":"1958.66"}],"object_url":"https://clevelandart.org/art/1958.66","image":{"src":"/images/cleveland/cma-1958-66.jpg","sourceUrl":"https://clevelandart.org/art/1958.66","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"This figure comes from the tomb of Duke Philip the Bold from the church of Champmol near Dijon (Burgundy, France). Philip, who founded the monastery and designated it as his burial place, hired the best artists, many of whom came from the Netherlands. While the commission was given in 1381, the work was not completed until 1410, six years after the duke’s death. This mourner is unusual for the time because it is not carved as a static low relief on the pedestal of the tomb but interacts with the viewers and their fellow procession members. The lifelike quality of the figure is due in large part to the alabaster. Its softness allowed artists to carve details into the material, and the transparent, milky white stone could also be polished to a high gloss."}},{"museum_id":"cleveland","language":"en","id":"cma-1963-256","position":118,"title":"Hours of Queen Isabella the Catholic, Queen of Spain","category":"Medieval Art","subtitle":null,"artist":"Master of the First Prayerbook of Maximillian (Flemish, c. 1444–1519) · Associates","facts":[{"label":"Date","value":"c. 1500"},{"label":"Medium","value":"ink, tempera, and gold on vellum"},{"label":"Accession","value":"1963.256"}],"object_url":"https://clevelandart.org/art/1963.256","image":{"src":"/images/cleveland/cma-1963-256.jpg","sourceUrl":"https://clevelandart.org/art/1963.256","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"The original owner of this exquisite book of hours was Queen Isabella of Spain, who sponsored Christopher Columbus's exploratory voyage to the Americas. Eventually this book found its way to the New World and was acquired by the Cleveland Museum of Art in 1963."}},{"museum_id":"cleveland","language":"en","id":"cma-1965-237","position":119,"title":"Jonah Swallowed","category":"Medieval Art","subtitle":null,"artist":null,"facts":[{"label":"Date","value":"280–90 CE"},{"label":"Medium","value":"marble"},{"label":"Culture","value":"Anatolia, late Roman-early Christian"},{"label":"Accession","value":"1965.237"}],"object_url":"https://clevelandart.org/art/1965.237","image":{"src":"/images/cleveland/cma-1965-237.jpg","sourceUrl":"https://clevelandart.org/art/1965.237","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"After disobeying the Lord’s command to proclaim judgment on the city of Nineveh, the Old Testament prophet Jonah was cast into the sea and swallowed by a sea monster. Here, the beast swallows Jonah headfirst."}},{"museum_id":"cleveland","language":"en","id":"cma-1966-3","position":120,"title":"St. Catherine of Siena and the Beggar","category":"Medieval Art","subtitle":null,"artist":"Giovanni di Paolo (Italian, c. 1403–1482)","facts":[{"label":"Date","value":"1460s"},{"label":"Medium","value":"tempera and gold on wood"},{"label":"Accession","value":"1966.3"}],"object_url":"https://clevelandart.org/art/1966.3","image":{"src":"/images/cleveland/cma-1966-3.jpg","sourceUrl":"https://clevelandart.org/art/1966.3","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"Saint Catherine (1347-1380) was the daughter of a prosperous Sienese cloth dyer. At the age of six, she saw a vision of Christ and thereafter dedicated herself to chastity, penance, and good works. She became much beloved in Siena for selflessly caring for victims of the Black Death. This panel, with 1966.2, was once part of a predella (or pedestal) of a large altarpiece painted for the Hospital Church of Siena. The main scene of this altarpiece, showing the Presentation of Christ in the Temple (now preserved in Siena) was ordered by the Pork Butchers Guild (the Pizzicaiuoli) in 1447. The predella was added later when Catherine was canonized in 1461. In the first panel, she kneels before an altar and reaches up to choose from the monastic garments offered by Saints Dominic, Augustine, and Francis, all founders of religious orders. Catherine takes the habit of Saint Dominic, which she wore as the founder of the Sisters of Penance. The second panel shows, at the right, Saint Catherine giving her cloak to a beggar. The beggar was really Christ in disguise, and at the left returns the cloak to her. For this act of charity, the cloak perpetually protected its wearer from the cold."}},{"museum_id":"cleveland","language":"en","id":"cma-1975-3","position":121,"title":"The Birth and Naming of John the Baptist","category":"Medieval Art","subtitle":null,"artist":"Juan de Flandes (Netherlandish, c. 1460–1519)","facts":[{"label":"Date","value":"1496–99"},{"label":"Medium","value":"oil on wood"},{"label":"Accession","value":"1975.3"}],"object_url":"https://clevelandart.org/art/1975.3","image":{"src":"/images/cleveland/cma-1975-3.jpg","sourceUrl":"https://clevelandart.org/art/1975.3","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"Typical of Flemish art of the period, this scene suggests a comfortable home of the late 1400s in the Netherlands to frame the story of a biblical birth. Elizabeth, mother of Saint John the Baptist, rests after her labor, while her cousin, the Virgin Mary, presents the newborn to his father, Zacharias. Having lost his ability to speak when he doubted an angel’s prophecy of the child’s birth, Zacharias writes down his son’s name. At this moment, his speech is restored. This painting was once part of an altarpiece commissioned by Queen Isabella I of Castile, known as the Catholic (1451–1504), for a monastery near Burgos."}},{"museum_id":"cleveland","language":"en","id":"cma-1938-431","position":122,"title":"Plaque","category":"Art of the Americas","subtitle":null,"artist":null,"facts":[{"label":"Date","value":"c. 500–200 BCE"},{"label":"Medium","value":"hammered and cut gold"},{"label":"Culture","value":"Peru, North Coast, Chongoyape(?), Chavín style (900-200 BCE)"},{"label":"Accession","value":"1938.431"}],"object_url":"https://clevelandart.org/art/1938.431","image":{"src":"/images/cleveland/cma-1938-431.jpg","sourceUrl":"https://clevelandart.org/art/1938.431","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"These plaques showing a powerful Chavín deity may come from a group of gold objects found in a lavish tomb in the 1920s. One is shaped as the deity’s fanged head, its fur transformed into sixteen serpents that edge the plaque. On the other, the deity’s visually elusive body also appears: the clawed hands over the chest may clutch a horizontal staff, an emblem of authority; across the waist is a belt that sprouts serpents; and beneath are the legs and feet, which stand atop fanged masks."}},{"museum_id":"cleveland","language":"en","id":"cma-1952-233","position":123,"title":"Backrest of a Litter","category":"Art of the Americas","subtitle":null,"artist":null,"facts":[{"label":"Date","value":"1185–1275 (radiocarbon date, 95.4% probability)"},{"label":"Medium","value":"mixed media: wood, gold alloy, pigment, shell inlay"},{"label":"Culture","value":"Central Andes, North Coast, Chimú people, late Intermediate period"},{"label":"Accession","value":"1952.233"}],"object_url":"https://clevelandart.org/art/1952.233","image":{"src":"/images/cleveland/cma-1952-233.jpg","sourceUrl":"https://clevelandart.org/art/1952.233","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"This rare, dramatic object served as the back support of a litter carried by human porters, a mode of transport reserved for honored members of many societies without draft animals or wheeled vehicles. The simple, bold figures—perhaps a Chimú lord and four officials—all wear wide collars, tunics, and crescent headdresses that are either brightly painted or covered with golden but now-corroded sheet metal. The holes at the bottom probably served as lashing points for a beam that supported the litter's seat."}},{"museum_id":"cleveland","language":"en","id":"cma-1953-386","position":124,"title":"Feast Ladle","category":"Art of the Americas","subtitle":null,"artist":null,"facts":[{"label":"Date","value":"late 1800s–early 1900s"},{"label":"Medium","value":"horn, bone, copper, abalone shell inlay"},{"label":"Culture","value":"Native North America, Northwest Coast, Alaska, Tlingit"},{"label":"Accession","value":"1953.386"}],"object_url":"https://clevelandart.org/art/1953.386","image":{"src":"/images/cleveland/cma-1953-386.jpg","sourceUrl":"https://clevelandart.org/art/1953.386","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"Elaborate utensils, valuable possessions of Northwest Coast noble clans, were used during potlatch feasts. An imposing eagle hovers, patron-like, over this ladle’s bowl and the bounty it once served; a bear’s head appears on the underside of the bowl. Both may be crests, motifs that, like European heraldry, were exclusive to important families and referred to their histories and rights to control land and resources."}},{"museum_id":"cleveland","language":"en","id":"cma-1961-31","position":125,"title":"Head Fragment","category":"Art of the Americas","subtitle":null,"artist":null,"facts":[{"label":"Date","value":"c. 900–300 BCE"},{"label":"Medium","value":"jadeite"},{"label":"Culture","value":"Mesoamerica, Mexico, Olmec"},{"label":"Accession","value":"1961.31"}],"object_url":"https://clevelandart.org/art/1961.31","image":{"src":"/images/cleveland/cma-1961-31.jpg","sourceUrl":"https://clevelandart.org/art/1961.31","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"This sensual head fragment may come from a seated or standing figure like those shown nearby, though much larger. The carving is exceptionally fine, from the slight under-eye puffiness to the delineation of the fleshy lips and the teeth. The profile face of supernatural being is incised just in front of each ear, perhaps indicating that the subject had special power."}},{"museum_id":"cleveland","language":"en","id":"cma-1962-32","position":126,"title":"Panel with Royal Woman","category":"Art of the Americas","subtitle":null,"artist":"K’in Lakam Chahk · Jun Nat Omootz","facts":[{"label":"Date","value":"c. 795"},{"label":"Medium","value":"limestone"},{"label":"Accession","value":"1962.32"}],"object_url":"https://clevelandart.org/art/1962.32","image":{"src":"/images/cleveland/cma-1962-32.jpg","sourceUrl":"https://clevelandart.org/art/1962.32","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"In this panel, probably from a palace interior, the woman’s static posture contrasts with the liveliness of the creature she holds, a god of royalty with a serpent leg and a grotesque head with a smoking torch on its brow. (The same deity is shown in the nearby Eccentric Flint.) Other signs of high rank are her jade jewelry and costume, its beauty suggesting that textiles and featherwork were great Maya arts, now lost to a tropical climate. The hieroglyphics refer to an undefined ritual that the woman completed in 795."}},{"museum_id":"cleveland","language":"en","id":"cma-1963-252","position":127,"title":"Mural Fragment with Elite Male and Maguey Cactus Leaves","category":"Art of the Americas","subtitle":null,"artist":null,"facts":[{"label":"Date","value":"500–550"},{"label":"Medium","value":"fresco on wall fragment"},{"label":"Culture","value":"Central Mexico, Tlacuilapaxco apartment compound(?), Teotihuacán style, Classic Period"},{"label":"Accession","value":"1963.252"}],"object_url":"https://clevelandart.org/art/1963.252","image":{"src":"/images/cleveland/cma-1963-252.jpg","sourceUrl":"https://clevelandart.org/art/1963.252","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"This richly dressed elite male belonged to a row of identical figures who processed along the walls of a patio in one of Teotihuacán’s wealthy apartment compounds. He offers a chant or prayer, materialized in a mouth scroll, along with a flower-filled libation that cascades from one hand. In the other hand, he carries an incense bag. The thorny spines of the maguey cactus, in front and behind, may allude to the offering of precious blood and a ritual beverage made from the cactus’s sap (pulque, a less refined form of tequila). The spines are thrust into objects that may represent bundles or plots of land."}},{"museum_id":"cleveland","language":"en","id":"cma-1967-29","position":128,"title":"Front Face of a Stela (Free-standing Stone with Relief)","category":"Art of the Americas","subtitle":null,"artist":null,"facts":[{"label":"Date","value":"692"},{"label":"Medium","value":"limestone"},{"label":"Culture","value":"Mesoamerica, Guatemala, Department of the Petén, El Perú (also known as Waka'), Maya (250-900), Classic period (200-1000)"},{"label":"Accession","value":"1967.29"}],"object_url":"https://clevelandart.org/art/1967.29","image":{"src":"/images/cleveland/cma-1967-29.jpg","sourceUrl":"https://clevelandart.org/art/1967.29","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"In stone sculpture, Maya rulers celebrated the milestones of their reigns with flamboyant portraits like this image of a royal woman, created to mark the passage of a twenty-year period known as the k’atun. She originally stood in a plaza next to a portrait of her spouse (see photo), with whom she ruled El Perú-Waka’, a provincial Maya town. A member of the powerful dynasty of a nearby Maya center, she seems to have held higher authority than her husband, serving as a military governor. Her costume reflects her status: the headdress has a fan of green quetzal feathers and her jewelry probably refers to jade-both among the most prized of ancient materials. Jade beads also may form the net over her garment, belted with the head of a fish-like creature. Completing the costume are the scepter and shield she grasps in her hands. The dwarf at her side may be a court attendant. The hieroglyphic text refers to important dynastic dates."}},{"museum_id":"cleveland","language":"en","id":"cma-1973-3","position":129,"title":"Ballgame Palma","category":"Art of the Americas","subtitle":null,"artist":null,"facts":[{"label":"Date","value":"c. 900–1100"},{"label":"Medium","value":"stone"},{"label":"Culture","value":"Mexico, Gulf Coast, Classic Veracruz style (600-1100)"},{"label":"Accession","value":"1973.3"}],"object_url":"https://clevelandart.org/art/1973.3","image":{"src":"/images/cleveland/cma-1973-3.jpg","sourceUrl":"https://clevelandart.org/art/1973.3","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"Stone palmas—so-called today for their palm frond-like shape—are ceremonial sculptures that may replicate lightweight gear worn over the chest during the ballgame. The scene on the back of this palma vividly illustrates the tie between the ballgame and sacrifice. A bat descends from the top, clutching severed human body parts, and at the center an upright figure brandishes a blade over a reclining victim. The scene's many animal figures, including the one on the front, may belong to ballgame mythology that now is lost."}},{"museum_id":"cleveland","language":"en","id":"cma-1984-37","position":130,"title":"Figure of a Warrior","category":"Art of the Americas","subtitle":null,"artist":null,"facts":[{"label":"Date","value":"after 1325 (thermoluminescence date of casting core, 1345–1575)"},{"label":"Medium","value":"gold-silver-copper alloy (cast)"},{"label":"Culture","value":"Central Mexico, Tetzcoco?, Aztec, Post-Classic Period"},{"label":"Accession","value":"1984.37"}],"object_url":"https://clevelandart.org/art/1984.37","image":{"src":"/images/cleveland/cma-1984-37.jpg","sourceUrl":"https://clevelandart.org/art/1984.37","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"The elite status of this warrior, who holds a dartthrower, darts, and a shield, is revealed by the gold from which he is made as well as his jewelry and sandals. Military accomplishment was prized by the Aztecs, whose imperial expansion was fueled by ambition as well as their belief that they were chosen to uphold cosmic order through war. The purpose of the chest cavity is unclear; the figurine may have been worn as a pendant."}},{"museum_id":"cleveland","language":"en","id":"cma-1991-20","position":131,"title":"\"Horned\" Male","category":"Art of the Americas","subtitle":null,"artist":null,"facts":[{"label":"Date","value":"100 BCE–300 CE"},{"label":"Medium","value":"earthenware with colored slips, black burial deposits"},{"label":"Culture","value":"West Mexico, Colima, Comala style"},{"label":"Accession","value":"1991.20"}],"object_url":"https://clevelandart.org/art/1991.20","image":{"src":"/images/cleveland/cma-1991-20.jpg","sourceUrl":"https://clevelandart.org/art/1991.20","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"This figure’s concentrated, otherworldly expression is emphasized by the hornlike element strapped to its forehead. This \"horn\" may be the spire of a conch shell, which comes from water and, therefore, refers to fertility—likely an important ritual concern of West Mexican chiefs. The element also could represent the \"horn of power\" worn in some areas of the world by shamans, the spiritual leaders and healers of small, nonindustrial societies."}},{"museum_id":"cleveland","language":"en","id":"cma-1918-328","position":132,"title":"The Age of Bronze","category":"Modern European Painting and Sculpture","subtitle":null,"artist":"Auguste Rodin (French, 1840–1917)","facts":[{"label":"Date","value":"1875–76"},{"label":"Medium","value":"bronze"},{"label":"Accession","value":"1918.328"}],"object_url":"https://clevelandart.org/art/1918.328","image":{"src":"/images/cleveland/cma-1918-328.jpg","sourceUrl":"https://clevelandart.org/art/1918.328","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"Rodin’s earliest surviving life-size sculpture, The Age of Bronze is an enigmatic and provocative image of a man awakening to new consciousness. The figure originally held a spear in one hand; by removing the weapon, Rodin stripped the sculpture of narrative symbols and focused on the sensuality and psychological power of the male nude. Contemporaries found the figure so realistic they falsely accused Rodin of making a cast from a living person. Museum trustee Ralph King commissioned this cast from the artist in 1916 with the intention of donating it to the museum. Rodin personally supervised the exceptionally fine casting and finished it with his favorite patina, a deep reddish tone he called “crushed grape.”"}},{"museum_id":"cleveland","language":"en","id":"cma-1942-647","position":133,"title":"The Burning of the Houses of Lords and Commons, 16 October 1834","category":"Modern European Painting and Sculpture","subtitle":null,"artist":"Joseph Mallord William Turner (British, 1775–1851)","facts":[{"label":"Date","value":"1835"},{"label":"Medium","value":"oil on canvas"},{"label":"Accession","value":"1942.647"}],"object_url":"https://clevelandart.org/art/1942.647","image":{"src":"/images/cleveland/cma-1942-647.jpg","sourceUrl":"https://clevelandart.org/art/1942.647","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"Fire consumed London’s famous Houses of Parliament on the night of October 16, 1834, and people gathered along the banks of the river Thames to gaze in awe at the horrifying spectacle. Initially, a low tide made it difficult to pump water to land and hampered steamers towing firefighting equipment along the river. The blaze burned uncontrollably for hours. J. M. W. Turner records the struggle as the boats in the lower-right corner head toward the flames. Although Turner based the painting on an actual event, he magnified the height of the flames, using the disaster as the starting point to express man’s helplessness when confronted with the destructive powers of nature. Brilliant swathes of color and variable atmospheric effects border on abstraction."}},{"museum_id":"cleveland","language":"en","id":"cma-1942-1065","position":134,"title":"Romaine Lacaux","category":"Modern European Painting and Sculpture","subtitle":null,"artist":"Pierre-Auguste Renoir (French, 1841–1919)","facts":[{"label":"Date","value":"1864"},{"label":"Medium","value":"oil on fabric"},{"label":"Accession","value":"1942.1065"}],"object_url":"https://clevelandart.org/art/1942.1065","image":{"src":"/images/cleveland/cma-1942-1065.jpg","sourceUrl":"https://clevelandart.org/art/1942.1065","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"This painting may be Renoir's earliest signed canvas. Its sensitive display of color and light communicates an ideal of delicate, youthful beauty. The luminous tones of the background drapery and of the child's white blouse result from the artist's careful observation of reflected light and color on translucent materials. The delicate nuances of color, particularly in the young girl's face, reveal Renoir's previous training as a decorator of porcelain. He painted this portrait, commissioned by the vacationing Lacaux family, during his stay at an artist's colony in the village of Barbizon, near Paris."}},{"museum_id":"cleveland","language":"en","id":"cma-1947-209","position":135,"title":"The Large Plane Trees (Road Menders at Saint-Rémy)","category":"Modern European Painting and Sculpture","subtitle":null,"artist":"Vincent van Gogh (Dutch, 1853–1890)","facts":[{"label":"Date","value":"1889"},{"label":"Medium","value":"oil on fabric"},{"label":"Accession","value":"1947.209"}],"object_url":"https://clevelandart.org/art/1947.209","image":{"src":"/images/cleveland/cma-1947-209.jpg","sourceUrl":"https://clevelandart.org/art/1947.209","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"Like Two Poplars in the Alpilles near Saint-Rémy (on view nearby), Vincent van Gogh painted this autumnal landscape while living in a psychiatric hospital near Saint-Rémy in southern France where he was treated for severe depression. Understanding that painting from nature eased his symptoms, Van Gogh’s physician permitted the artist to paint landscapes outside. Van Gogh described this painting in a letter to his brother Theo: “The last study I did is a view of the village, where they were at work under some enormous plane trees—repairing the pavements. . . . There are heaps of sand, stones, and the gigantic trunks—the leaves yellowing and here and there you can get a glimpse of a house front and small figures.”"}},{"museum_id":"cleveland","language":"en","id":"cma-1958-21","position":136,"title":"Mount Sainte-Victoire","category":"Modern European Painting and Sculpture","subtitle":null,"artist":"Paul Cezanne (French, 1839–1906)","facts":[{"label":"Date","value":"c. 1904"},{"label":"Medium","value":"oil on fabric"},{"label":"Accession","value":"1958.21"}],"object_url":"https://clevelandart.org/art/1958.21","image":{"src":"/images/cleveland/cma-1958-21.jpg","sourceUrl":"https://clevelandart.org/art/1958.21","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"During the last 20 years of his life, Cezanne repeatedly painted Mount Sainte-Victoire near his home in Aix-en-Provence in southern France. Cezanne painted this view from life at one of his favorite sites, a small road that led from Aix eastward toward Mount Sainte-Victoire. He set up his easel at the edge of the road where he could see two umbrella pines and the mountain towering over the scene. A branch of one of the pines extends from the left of the canvas across the sky, echoing the slope of the mountain, linking the near and the far."}},{"museum_id":"cleveland","language":"en","id":"cma-1958-39","position":137,"title":"The Red Kerchief","category":"Modern European Painting and Sculpture","subtitle":null,"artist":"Claude Monet (French, 1840–1926)","facts":[{"label":"Date","value":"c. 1868–73"},{"label":"Medium","value":"oil on fabric"},{"label":"Accession","value":"1958.39"}],"object_url":"https://clevelandart.org/art/1958.39","image":{"src":"/images/cleveland/cma-1958-39.jpg","sourceUrl":"https://clevelandart.org/art/1958.39","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"This painting depicts Monet's first wife, Camille, outside on a snowy day passing by the French doors of their home at Argenteuil. Her face is rendered in a radically bold Impressionist technique of mere daubs of paint quickly applied, just as the snow and trees are defined by broad, broken strokes of pure white and green."}},{"museum_id":"cleveland","language":"en","id":"cma-1960-81","position":138,"title":"Water Lilies (Agapanthus)","category":"Modern European Painting and Sculpture","subtitle":null,"artist":"Claude Monet (French, 1840–1926)","facts":[{"label":"Date","value":"c. 1915–26"},{"label":"Medium","value":"oil on canvas"},{"label":"Accession","value":"1960.81"}],"object_url":"https://clevelandart.org/art/1960.81","image":{"src":"/images/cleveland/cma-1960-81.jpg","sourceUrl":"https://clevelandart.org/art/1960.81","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"A skilled horticulturalist as well as an artist, Claude Monet spent the last 30 years of his life painting the private garden he designed and helped cultivate at his home in Giverny in northern France. The resultant canvases are notable for their varied motifs, formats, and sizes. Monumental in scale, this rendering of his water lily pond focuses on the momentary effects of sunlight as it both penetrates and reflects off its shimmering surface. By zeroing in on the water and omitting its horizon and surrounding banks, Monet infers a limitless expanse—a perception amplified by the painting’s vast horizontal format that fills the viewer’s field of vision."}},{"museum_id":"cleveland","language":"en","id":"cma-1962-37","position":139,"title":"Cupid and Psyche","category":"Modern European Painting and Sculpture","subtitle":null,"artist":"Jacques-Louis David (French, 1748–1825)","facts":[{"label":"Date","value":"1817"},{"label":"Medium","value":"oil on canvas"},{"label":"Accession","value":"1962.37"}],"object_url":"https://clevelandart.org/art/1962.37","image":{"src":"/images/cleveland/cma-1962-37.jpg","sourceUrl":"https://clevelandart.org/art/1962.37","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"David used the story of Cupid and Psyche to explore the conflict between idealized love and physical reality. Cupid, lover of the beautiful mortal Psyche, visited her nightly on the condition that she not know his identity. Cupid was usually depicted as an ideal adolescent, but here David presents him as an ungainly teenager smirking at his sexual conquest. David took inspiration from a number of ancient texts, including an obscure, recently published Greek poem by Moschus that describes Cupid as a mean-spirited brat with flashing eyes and curly hair."}},{"museum_id":"cleveland","language":"en","id":"cma-1963-91","position":140,"title":"La Cervara, the Roman Campagna","category":"Modern European Painting and Sculpture","subtitle":null,"artist":"Jean Baptiste Camille Corot (French, 1796–1875)","facts":[{"label":"Date","value":"c. 1830–31"},{"label":"Medium","value":"oil on fabric"},{"label":"Accession","value":"1963.91"}],"object_url":"https://clevelandart.org/art/1963.91","image":{"src":"/images/cleveland/cma-1963-91.jpg","sourceUrl":"https://clevelandart.org/art/1963.91","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"Corot based his large oil painting on drawings and oil sketches made outdoors. Attracted to the beauty of the Italian countryside, he often sketched around Rome, where he lived from 1825 to 1828. This painting's highly structured composition, based on forms moving into the distance along a series of diagonals, is characteristic of Corot's early style and recalls the classical landscapes of 17th-century painter Nicholas Poussin."}},{"museum_id":"cleveland","language":"en","id":"cma-1921-1239","position":141,"title":"Portrait of Dora Wheeler","category":"American Painting and Sculpture","subtitle":null,"artist":"William Merritt Chase (American, 1849–1916)","facts":[{"label":"Date","value":"1882–83"},{"label":"Medium","value":"oil on canvas"},{"label":"Accession","value":"1921.1239"}],"object_url":"https://clevelandart.org/art/1921.1239","image":{"src":"/images/cleveland/cma-1921-1239.jpg","sourceUrl":"https://clevelandart.org/art/1921.1239","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"Dora Wheeler became Chase's first student when he returned from overseas study in Munich and set up a teaching studio in New York. At the time, few American artists accepted women as private pupils. After her course of study, Wheeler joined her mother in launching a successful decorating firm, one of the first businesses in the country to be operated entirely by women. For the firm, she designed luxurious textiles, and the embroidered silk tapestry that fills the background in her portrait references her occupational interest. Chase's portrait was awarded a gold medal at an international exhibition of contemporary art in Munich in 1883, and later that year was also shown in Paris. At some later point, the painting was acquired by the sitter, who subsequently donated it to the museum."}},{"museum_id":"cleveland","language":"en","id":"cma-1922-1133","position":142,"title":"Stag at Sharkey's","category":"American Painting and Sculpture","subtitle":null,"artist":"George Bellows (American, 1882–1925)","facts":[{"label":"Date","value":"1909"},{"label":"Medium","value":"oil on canvas"},{"label":"Accession","value":"1922.1133"}],"object_url":"https://clevelandart.org/art/1922.1133","image":{"src":"/images/cleveland/cma-1922-1133.jpg","sourceUrl":"https://clevelandart.org/art/1922.1133","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"Bellows was no stranger to Sharkey’s Athletic Club, a raucous saloon with a backroom boxing ring, located near his studio. Founded by Tom “Sailor” Sharkey, an ex-fighter who had also served in the US Navy, the club attracted men seeking to watch or participate in matches. Because public boxing was illegal in New York at the time, a private event had to be arranged in order for a bout to take place. Participation was usually limited to members of a particular club, but whenever an outsider competed, he was given temporary membership and known as a “stag.” Although boxing had its share of detractors who considered it uncouth at best or barbaric at worst, its proponents—among them President Theodore Roosevelt—regarded it a healthy manifestation of manliness. Around the time Bellows painted Stag at Sharkey’s, boxing was moving from a predominantly working-class enterprise to one with greater genteel appeal. For some contemporaries, boxing was a powerful analogy for the notion that only the strongest and fittest would flourish in modern society."}},{"museum_id":"cleveland","language":"en","id":"cma-1927-393","position":143,"title":"Elizabeth Shewell West and Her Son, Raphael","category":"American Painting and Sculpture","subtitle":null,"artist":"Benjamin West (American, born The Thirteen Colonies, 1738–1820)","facts":[{"label":"Date","value":"c. 1770"},{"label":"Medium","value":"oil on canvas"},{"label":"Accession","value":"1927.393"}],"object_url":"https://clevelandart.org/art/1927.393","image":{"src":"/images/cleveland/cma-1927-393.jpg","sourceUrl":"https://clevelandart.org/art/1927.393","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"West was the first American artist to study in Italy, where he spent three years before permanently settling in London. He so admired the artistic ideals of the Italian Renaissance master Raphael that he named his eldest son after him, and he imitated Raphael’s celebrated Madonna of the Chair when composing this tender double portrait of his wife and child."}},{"museum_id":"cleveland","language":"en","id":"cma-1927-1984","position":144,"title":"The Biglin Brothers Turning the Stake","category":"American Painting and Sculpture","subtitle":null,"artist":"Thomas Eakins (American, 1844–1916)","facts":[{"label":"Date","value":"1873"},{"label":"Medium","value":"oil on canvas"},{"label":"Accession","value":"1927.1984"}],"object_url":"https://clevelandart.org/art/1927.1984","image":{"src":"/images/cleveland/cma-1927-1984.jpg","sourceUrl":"https://clevelandart.org/art/1927.1984","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"Eakins's painting celebrates athletic teamwork while commemorating an actual event, a famous rowing race that took place on the Schuylkill River in Philadelphia during May 1872. Throngs of spectators line the riverbank and watch as Barney and John Biglin negotiate the tricky turn around a stake marking the halfway point in the contest. Their competitors, seen in the middle distance at the right, lag behind. The Biglin brothers won the race, cementing their status as the most celebrated oarsmen of the era. Trained in the United States and France, Eakins spent almost his entire artistic career in his hometown of Philadelphia. He is renowned for the unsentimental realism in his paintings, whose compositions he developed through painstakingly prepared figure and perspective drawings."}},{"museum_id":"cleveland","language":"en","id":"cma-1928-8","position":145,"title":"The Race Track (Death on a Pale Horse)","category":"American Painting and Sculpture","subtitle":null,"artist":"Albert Pinkham Ryder (American, 1847–1917)","facts":[{"label":"Date","value":"c. 1896–1908"},{"label":"Medium","value":"oil on canvas"},{"label":"Accession","value":"1928.8"}],"object_url":"https://clevelandart.org/art/1928.8","image":{"src":"/images/cleveland/cma-1928-8.jpg","sourceUrl":"https://clevelandart.org/art/1928.8","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"Ryder’s subject was inspired by a horse race that took place in New York during 1888. One of the artist’s friends wagered $500 on the race and then died by suicide after the horse lost. Medieval symbolism infuses the composition: death appears as a skeleton on horseback holding a scythe with which it cuts down the living, while a snake—a sign of temptation and evil—slithers in the foreground. An intense man, Ryder worked on the painting for several years and was deeply reluctant to part with it."}},{"museum_id":"cleveland","language":"en","id":"cma-1958-42","position":146,"title":"Morning Glory with Black","category":"American Painting and Sculpture","subtitle":null,"artist":"Georgia O'Keeffe (American, 1887–1986)","facts":[{"label":"Date","value":"1926"},{"label":"Medium","value":"oil on canvas"},{"label":"Accession","value":"1958.42"}],"object_url":"https://clevelandart.org/art/1958.42","image":{"src":"/images/cleveland/cma-1958-42.jpg","sourceUrl":"https://clevelandart.org/art/1958.42","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"O'Keeffe is best known for close-up flower subjects whose magnified forms fill the entire space of each canvas. Likely inspired by similar compositions in modern photography, these images are not only celebrations of nature, but also striking essays in abstract design. Although many critics interpreted O'Keeffe's flower paintings as reflections of femininity in general and female sexuality in particular, the artist strongly opposed such readings. Throughout most of her career, she frequently attempted to persuade others to discuss her work without referring to her gender, writing on one occasion, \"I have always been very annoyed at being referred to as a 'woman artist' rather than an 'artist.'\""}},{"museum_id":"cleveland","language":"en","id":"cma-1965-233","position":147,"title":"Twilight in the Wilderness","category":"American Painting and Sculpture","subtitle":null,"artist":"Frederic Edwin Church (American, 1826–1900)","facts":[{"label":"Date","value":"1860"},{"label":"Medium","value":"oil on canvas"},{"label":"Accession","value":"1965.233"}],"object_url":"https://clevelandart.org/art/1965.233","image":{"src":"/images/cleveland/cma-1965-233.jpg","sourceUrl":"https://clevelandart.org/art/1965.233","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"In his New York studio, Church painted this spectacular view of a blazing sunset over wilderness near Mount Katahdin in Maine, which he had sketched during a visit nearly two years earlier. Although Church often extolled the grandeur of American landscape in his work, this painting appears to have additional overtones. Created on the eve of the Civil War, the painting's subject can be interpreted as symbolically evoking the coming conflagration. Church's considerable technical skills and clever showmanship contributed to his fame as the premier artist of his generation. Rather than debut this painting in an annual exhibition with works by other artists as was the custom, Church instead exhibited it by itself at a prestigious art gallery. Coaxed by advance publicity and highly favorable press reviews, several hundred spectators flocked to admire it during its seven-week run."}},{"museum_id":"cleveland","language":"en","id":"cma-1977-43","position":148,"title":"Church Street El","category":"American Painting and Sculpture","subtitle":null,"artist":"Charles Sheeler (American, 1883–1965)","facts":[{"label":"Date","value":"1920"},{"label":"Medium","value":"oil on canvas"},{"label":"Accession","value":"1977.43"}],"object_url":"https://clevelandart.org/art/1977.43","image":{"src":"/images/cleveland/cma-1977-43.jpg","sourceUrl":"https://clevelandart.org/art/1977.43","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"Capturing the soaring heights of New York City, this painting is a dramatic bird's-eye view of Broadway and Wall Street, showing a conglomeration of buildings at left and center, and the Church Street elevated train at right. Sheeler based his composition on an image from the short movie Manhatta (1920-21), which he made with the photographer Paul Strand. One of the first avant-garde American films, Manhatta celebrates the dynamic metropolis through a series of carefully composed shots of Lower Manhattan. As typical with Sheeler's work, the artist simplified forms and eliminated textures in Church Street El to concentrate on rhythmic interplay of shapes and color, and patterns of light and shadow."}},{"museum_id":"cleveland","language":"en","id":"cma-1938-9","position":149,"title":"Cranes and Serpents","category":"Chinese Art","subtitle":null,"artist":null,"facts":[{"label":"Date","value":"475–221 BCE"},{"label":"Medium","value":"lacquered wood with polychromy"},{"label":"Culture","value":"China, reportedly from Hunan province, Changsha, Warring States period (475–221 BCE), State of Chu (c. 1046–223 BCE)"},{"label":"Accession","value":"1938.9"}],"object_url":"https://clevelandart.org/art/1938.9","image":{"src":"/images/cleveland/cma-1938-9.jpg","sourceUrl":"https://clevelandart.org/art/1938.9","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"A different style of ritual art developed in the state of Chu in South China. In addition to bronze vessels, lacquered wood artifacts expanded the repertory of ritual implements. This extraordinary sculpture was probably a drum stand for supporting a suspended drum in ritual ceremonies. It is unique among other excavated drum stands of the Chu, which typically show two birds standing on tigers. The theme of the bird stepping on the serpent was common in the Chu visual culture. Yet the slender proportions and seemingly flimsy structure of this particular set raise the question of whether it was utilitarian or mostly served symbolic functions in the tomb. The birds' and serpents' bodies have designs painted in red lacquer and yellow pigment against the black lacquer. Scientific analyses confirm the additional use of a blue or green pigment that has been discolored over time."}},{"museum_id":"cleveland","language":"en","id":"cma-1944-190","position":150,"title":"Amphora Vase","category":"Chinese Art","subtitle":null,"artist":null,"facts":[{"label":"Date","value":"1723–35"},{"label":"Medium","value":"porcelain with celadon glaze"},{"label":"Culture","value":"China, Jiangxi Province, Jingdezhen, Qing dynasty (1644–1911), Yongzheng mark and period (1723–35)"},{"label":"Accession","value":"1944.190"}],"object_url":"https://clevelandart.org/art/1944.190","image":{"src":"/images/cleveland/cma-1944-190.jpg","sourceUrl":"https://clevelandart.org/art/1944.190","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"This elegant vase, modeled in the shape of an amphora with dragon handles has perfect symmetry. Its celadon glaze is of exceptional purity and of subtle green color, all characteristics of classical Yongzheng-era monochrome porcelains. The amphora shape and dragon handles of this vase, seen earlier in the glazed stoneware of the Sui and Tang dynasties (581-907), were revived during the Yongzheng period for achieving \"antique-elegance\" (guya) in aesthetics as well as technical perfection in ceramic art. Only four vases of this size and glaze are known to exist."}},{"museum_id":"cleveland","language":"en","id":"cma-1953-628","position":151,"title":"Amulet in the Form of a Seated Figure with Bovine Head","category":"Chinese Art","subtitle":null,"artist":null,"facts":[{"label":"Date","value":"c. 4700–2920 BCE"},{"label":"Medium","value":"jade (nephrite)"},{"label":"Culture","value":"Northeast China, Neolithic period, probably Hongshan culture (4700–2920 BCE)"},{"label":"Accession","value":"1953.628"}],"object_url":"https://clevelandart.org/art/1953.628","image":{"src":"/images/cleveland/cma-1953-628.jpg","sourceUrl":"https://clevelandart.org/art/1953.628","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"With a bovine head and four horns, this seated figurine was a powerful ritual and shamanic symbol. Drill holes above its shoulders form two interconnected perforations for suspension, suggesting that the jade was originally used as a pendant, presumably by the shaman performing the tasks of journeying to and communicating with the supernatural realms."}},{"museum_id":"cleveland","language":"en","id":"cma-1957-40","position":152,"title":"Brush Washer","category":"Chinese Art","subtitle":null,"artist":null,"facts":[{"label":"Date","value":"late 1000s–1127"},{"label":"Medium","value":"porcelaneous stoneware, Ru ware"},{"label":"Culture","value":"China, Henan Province, Baofeng, Qingliangsi, Northern Song dynasty (960-1127)"},{"label":"Accession","value":"1957.40"}],"object_url":"https://clevelandart.org/art/1957.40","image":{"src":"/images/cleveland/cma-1957-40.jpg","sourceUrl":"https://clevelandart.org/art/1957.40","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"Ru ware is the rarest and most celebrated of all Chinese imperial wares. It was made for the late Northern Song court for a very short time and was therefore extremely rare and precious. Simplicity and refined elegance are Ru ware's hallmarks. Its graceful shape, soft luster, and subtle color variation of the glaze interact in perfect unity. Other physical characteristics include an ash-grey body, soft greyblue glaze with a fine crackle, as well as small sesame-seed spur marks on the base."}},{"museum_id":"cleveland","language":"en","id":"cma-1957-61","position":153,"title":"Wine Cup with Children at Play","category":"Chinese Art","subtitle":null,"artist":null,"facts":[{"label":"Date","value":"1465–87"},{"label":"Medium","value":"porcelain with underglaze blue and overglaze enamel decoration, docai (\"joined colors\") ware"},{"label":"Culture","value":"China, Jiangxi province, Jingdezhen, Ming dynasty (1368-1644), Chenghua mark and period (1465-1487)"},{"label":"Accession","value":"1957.61"}],"object_url":"https://clevelandart.org/art/1957.61","image":{"src":"/images/cleveland/cma-1957-61.jpg","sourceUrl":"https://clevelandart.org/art/1957.61","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"This delicate wine cup, only two inches high, exhibits free, spontaneous drawing as well as perfect compositional balance over its small surface area. The motifs were outlined with cobalt blue; the piece was then glazed and fired in the normal way for making the blue-and-white ware. After firing, the outline painting was completed with colored enamels over the glaze. The piece was fired the second time. The pictorial decoration is refined and complicated; the porcelain body is of exceptionally high quality and is thin, translucent, and light in weight."}},{"museum_id":"cleveland","language":"en","id":"cma-1962-154","position":154,"title":"Jar with Lion-Head Handles","category":"Chinese Art","subtitle":null,"artist":null,"facts":[{"label":"Date","value":"1300s"},{"label":"Medium","value":"porcelain with underglaze painted decoration"},{"label":"Culture","value":"China, Jiangxi Province, Jingdezhen, Yuan dynasty (1271–1368)"},{"label":"Accession","value":"1962.154"}],"object_url":"https://clevelandart.org/art/1962.154","image":{"src":"/images/cleveland/cma-1962-154.jpg","sourceUrl":"https://clevelandart.org/art/1962.154","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"Appreciated for its strong profile, brilliant blue color, and firm delineation of the decorative patterns, this jar is a classic example of Yuan dynasty blue-and-white ware. This type of ware was produced no later than the 1330s for both domestic use (the court and common people alike) and overseas trade. This example testifies to the transmission of artistic ideas and techniques between China and the rest of the great Mongol Empire as a result of trade. The cobalt that was used for the blue underglaze decoration was imported from Iran, likely from Kashan. The band of cloud-collar motifs with phoenixes set against floral grounds, as shown here, is an artistic vocabulary that can also be found in Iranian decorative arts of the Ilkhanid period (1256–1353)."}},{"museum_id":"cleveland","language":"en","id":"cma-1971-145","position":155,"title":"Vase with Golden Pheasants","category":"Chinese Art","subtitle":null,"artist":null,"facts":[{"label":"Date","value":"1736–95"},{"label":"Medium","value":"porcelain painted in polychrome enamels over transparent glaze"},{"label":"Culture","value":"China, Jiangxi province, Jingdezhen kilns, Qing dynasty (1644-1911), Qianlong mark and period (1736-95)"},{"label":"Accession","value":"1971.145"}],"object_url":"https://clevelandart.org/art/1971.145","image":{"src":"/images/cleveland/cma-1971-145.jpg","sourceUrl":"https://clevelandart.org/art/1971.145","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"The flower-and-bird painting in this vase was intricately executed in colored enamels (falangcai), with careful modeling, shading, and blending of colors reflecting European influences through missionary-artists at the Qing court. The Jesuit artist Giuseppe Castiglione (1688–1766), in particular, exerted tremendous impact at the Qianlong academy."}},{"museum_id":"cleveland","language":"en","id":"cma-1973-74","position":156,"title":"Mirror with Phoenixes, Birds, Butterflies, and Floral Sprays","category":"Chinese Art","subtitle":null,"artist":null,"facts":[{"label":"Date","value":"700s"},{"label":"Medium","value":"bronze with silver and gold inlaid lacquer"},{"label":"Culture","value":"China, Tang dynasty (618-907)"},{"label":"Accession","value":"1973.74"}],"object_url":"https://clevelandart.org/art/1973.74","image":{"src":"/images/cleveland/cma-1973-74.jpg","sourceUrl":"https://clevelandart.org/art/1973.74","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"This extremely rare pingtuo mirror is coated with a lacquer base inlaid with paper-thin sheets of silver and gold. The decorative patterns, especially the floral arabesques and the phoenixes and birds holding branches in their mouths, have a pronounced Persian and Central Asian flavor. Luxury items like this had been used by the Tang emperor as diplomatic gifts. A similar example from the Japanese imperial collection of Emperor Shōmu was donated by Empress Kōmyō in 756 to the Shōsō-in repository of the Tōdai-ji Temple, Nara, Japan."}},{"museum_id":"cleveland","language":"en","id":"cma-1915-495","position":157,"title":"Lamellophone (chisanji)","category":"African Art","subtitle":null,"artist":null,"facts":[{"label":"Date","value":"late 1800s"},{"label":"Medium","value":"Wood, iron, and wire"},{"label":"Culture","value":"Africa, Central Africa, Democratic Republic of the Congo or Angola, Chokwe-style maker"},{"label":"Accession","value":"1915.495"}],"object_url":"https://clevelandart.org/art/1915.495","image":{"src":"/images/cleveland/cma-1915-495.jpg","sourceUrl":"https://clevelandart.org/art/1915.495","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"The thumb piano portrays a wonderfully animated man riding a curious quadruped. His hat suggests he is probably a trader (pombeiro) engaged in long-distance commerce."}},{"museum_id":"cleveland","language":"en","id":"cma-1938-6","position":158,"title":"Ancestral Commemorative Head (uhunmwun-elao)","category":"African Art","subtitle":null,"artist":null,"facts":[{"label":"Date","value":"possibly mid-1500s or early 1600s"},{"label":"Medium","value":"Copper alloy and iron"},{"label":"Culture","value":"Nigeria, Benin Kingdom, Ẹdo peoples, members of the Igun Eronmwon (royal brasscasters) guild"},{"label":"Accession","value":"1938.6"}],"object_url":"https://clevelandart.org/art/1938.6","image":{"src":"/images/cleveland/cma-1938-6.jpg","sourceUrl":"https://clevelandart.org/art/1938.6","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"Brass heads are among many objects a new Ọba commissions when dedicating a shrine to their predecessor. This head of an Ọba wears layered necklaces of royal coral beads. Tubular beads adorn both the netted cap and slender braids alongside his temples. While representing an individual, his facial features and calm expression are idealized. The thickly cast head once supported a tusk. Immune to corrosion, brass symbolizes royal permanence. A personal religious object, this head sat on an ancestral altar in the Ọba’s palace. Like many works taken from Benin altars, this contrasts with its present-day public display in an American museum."}},{"museum_id":"cleveland","language":"en","id":"cma-1961-198","position":159,"title":"Nursing Woman with Child","category":"African Art","subtitle":null,"artist":null,"facts":[{"label":"Date","value":"1800s-1900s"},{"label":"Medium","value":"Wood and organic material"},{"label":"Culture","value":"Africa, West Africa, Côte d'Ivoire, reportedly Korhogo area, Senufo-style carver"},{"label":"Accession","value":"1961.198"}],"object_url":"https://clevelandart.org/art/1961.198","image":{"src":"/images/cleveland/cma-1961-198.jpg","sourceUrl":"https://clevelandart.org/art/1961.198","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"Beyond its specific depiction of a mother nursing her child, this sculpture symbolizes a larger concept of ancestral motherhood that is central to Senufo society, in which cultural inheritance is matrilineal. The darkened areas of wood come from oils applied to its surface as both libations and surface protectants. In some Senufo beliefs, one of the most important founding ancestors is the Great Mother or Ancient Woman (Katyeleeo or Maleeo). In groups that believe in the Great Mother, she suckles male initiates with the \"milk of knowledge.\" Through this process, youths gain the information they need to become adults (that is, fully human). The simplified appearance of the \"child\" in this sculpture reflects his unformed, pre-initiated state."}},{"museum_id":"cleveland","language":"en","id":"cma-1985-1082","position":160,"title":"Mask (mbap mteng): Elephant (aka)","category":"African Art","subtitle":null,"artist":null,"facts":[{"label":"Date","value":"early 1900s"},{"label":"Medium","value":"Cotton, burlap, glass beads, twine, leather, and wood"},{"label":"Culture","value":"Africa, Central Africa, Cameroon, Grassfields region, Bamileke-style maker"},{"label":"Accession","value":"1985.1082"}],"object_url":"https://clevelandart.org/art/1985.1082","image":{"src":"/images/cleveland/cma-1985-1082.jpg","sourceUrl":"https://clevelandart.org/art/1985.1082","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"The name given to masks like this, mbap mteng, means \"animal with huge ears.\" In the Cameroon Grassfields kingdoms, the elephant signifies power, authority, prestige, and leadership. The colorful glass beads that decorate the mask’s surface were imported from Venice and Bohemia (in Europe) and signal wealth and prosperity. Its geometric patterns include triangles that evoke the leopard, another animal linked with royal power. Members of Kuosi, an elite male society, wore such elephant masks for ritual dances and funerary ceremonies. This mask would have been worn with a costume that included a feather headdress"}},{"museum_id":"cleveland","language":"en","id":"cma-1990-22","position":161,"title":"Memorial head (nsodie)","category":"African Art","subtitle":null,"artist":null,"facts":[{"label":"Date","value":"late 1600s–early 1700s"},{"label":"Medium","value":"Terracotta"},{"label":"Culture","value":"Ghana, Akan-style sculpture, unknown female ceramicist"},{"label":"Accession","value":"1990.22"}],"object_url":"https://clevelandart.org/art/1990.22","image":{"src":"/images/cleveland/cma-1990-22.jpg","sourceUrl":"https://clevelandart.org/art/1990.22","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"This is an idealized portrait of an Akan royal. The Akan states formed in West Africa around the 1400s. Akan royal family members commissioned terracotta portraits like this from female artists during someone’s life. Following their death and burial, the family placed these sculptures in a sacred grove. The woman who sculpted this head over 300 years ago worked from memory, without sketches. The resulting sculpture combined idealized physical qualities of elite figures with individual details. The hairstyle and skin color of this portrait reflect its subject’s individuality. In contrast, his calm expression reflects the desired “cool composure” of elites."}},{"museum_id":"cleveland","language":"en","id":"cma-1995-21","position":162,"title":"Head","category":"African Art","subtitle":null,"artist":null,"facts":[{"label":"Date","value":"thermoluminescence date 20–620 CE"},{"label":"Medium","value":"terracotta"},{"label":"Culture","value":"Africa, West Africa, Nigeria, Nok-culture style region, unknown female ceramicist"},{"label":"Accession","value":"1995.21"}],"object_url":"https://clevelandart.org/art/1995.21","image":{"src":"/images/cleveland/cma-1995-21.jpg","sourceUrl":"https://clevelandart.org/art/1995.21","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"More than 500 such sculptures—often full figures with elaborate hairstyles and jewelry— have been found in central Nigeria. Named after a discovery site, Nok culture (500 BCE–200 CE or 1500–1 BCE) produced the earliest large figurative artworks in Africa outside of Egypt. Little was known about their social context, as they were first found in mining deposits in the 1920s. Archaeological excavations conducted in the 2000s by a German-Nigerian team suggest that many sculptures were deliberately broken and placed under pavements and in pits, indicating ritual practice. Male-centered art histories presumed men made these figurative sculptures; however, they incorporate building and firing techniques practiced only by women."}},{"museum_id":"cleveland","language":"en","id":"cma-1997-180","position":163,"title":"Prestige Cap (mpu ngola)","category":"African Art","subtitle":null,"artist":null,"facts":[{"label":"Date","value":"late 1800s–early 1900s"},{"label":"Medium","value":"Raffia palm fiber (Raphia ruffia or R. vinifera) and leopard claws"},{"label":"Culture","value":"Africa, Central Africa, Democratic Republic of Congo, Republic of Congo, or Cabinda (Angola), Kongo-style maker, possibly Yombe subgroup"},{"label":"Accession","value":"1997.180"}],"object_url":"https://clevelandart.org/art/1997.180","image":{"src":"/images/cleveland/cma-1997-180.jpg","sourceUrl":"https://clevelandart.org/art/1997.180","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"Zimpu (singular: mpu) are intricately knotted caps worn by men in parts of Central Africa. Ringed with leopard claws, this long cap (mpu ngola) once belonged to a high-status man; the fierce feline attachments alluded to his personal qualities, as both were seen as leaders in their domains. Its interlacing motifs appear across artforms made by the Kongo, Vili, and Yombe peoples. When new, caps draped over the head. However, raffia fibers stiffen over time. To support this now-delicate ngola, the CMA’s conservators mounted it upright. Known since at least 1607 in the former Loango Kingdom, as well as the adjacent Kongo Kingdom, such caps were once made by noblemen and worn into at least the 1980s."}},{"museum_id":"cleveland","language":"en","id":"cma-1930-331","position":164,"title":"Nataraja, Shiva as the Lord of Dance","category":"Indian and Southeast Asian Art","subtitle":null,"artist":null,"facts":[{"label":"Date","value":"1000s"},{"label":"Medium","value":"Bronze"},{"label":"Culture","value":"South India, Tamil Nadu, Chola period (900–1200s)"},{"label":"Accession","value":"1930.331"}],"object_url":"https://clevelandart.org/art/1930.331","image":{"src":"/images/cleveland/cma-1930-331.jpg","sourceUrl":"https://clevelandart.org/art/1930.331","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"One of the most celebrated sculptural forms in the history of Indian art, this elegant and dynamic figure embodies some of Hinduism’s most fundamental tenets. According to Hindu thought, time is cyclical; the world is created, maintained, preserved for a time, then destroyed, only to be created again an infinite number of times. For those Hindus who view Shiva to be the all-powerful creator divinity, he is responsible for both creation and destruction. The ring of fire and the tongue of flame he holds in his left hand refer to destruction, and the drum in his raised right hand refers to the relentless beat of time as it moves inevitably forward. His lower right hand, held up with the palm facing out, signals to his devotees not to be afraid of the impending destruction; they can be liberated from the cycles of birth and death through devotion to him, which he indicates by pointing to his upraised foot. With every step in his dance, he lands on a dwarfish figure personifying ignorance."}},{"museum_id":"cleveland","language":"en","id":"cma-1968-40","position":165,"title":"Standing Buddha","category":"Indian and Southeast Asian Art","subtitle":null,"artist":null,"facts":[{"label":"Date","value":"591"},{"label":"Medium","value":"bronze"},{"label":"Culture","value":"Northern India, Uttar Pradesh"},{"label":"Accession","value":"1968.40"}],"object_url":"https://clevelandart.org/art/1968.40","image":{"src":"/images/cleveland/cma-1968-40.jpg","sourceUrl":"https://clevelandart.org/art/1968.40","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"This bronze Buddha is exceptional, because it carries an inscription on its base that dates its manufacture to the year 591. According to the inscription, the sculpture was dedicated by a nun who was from a village in Nepal, but she probably commissioned it at a workshop in northern India. The Buddha's robe on this image has been left plain, without pleat lines to obscure the beauty of the contours of the body. Only the rippling scalloped clusters of the garment’s hem lend some sense of energy and subtle ornament to the composition."}},{"museum_id":"cleveland","language":"en","id":"cma-1970-12","position":166,"title":"Mother Goddess","category":"Indian and Southeast Asian Art","subtitle":null,"artist":null,"facts":[{"label":"Date","value":"c. 600"},{"label":"Medium","value":"schist"},{"label":"Culture","value":"Northwestern India, Rajasthan, Udaipur District"},{"label":"Accession","value":"1970.12"}],"object_url":"https://clevelandart.org/art/1970.12","image":{"src":"/images/cleveland/cma-1970-12.jpg","sourceUrl":"https://clevelandart.org/art/1970.12","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"Sets of mother goddesses were installed in shrines near the entrance to Hindu temples. From one of the most naturalistic and charming sets, this mother attentively grasps the wrist of her toddler to gently guide him, while smiling lovingly and patiently at him. The simplicity of garments and ornament is characteristic of sculpture of the sixth century, and the naturalistic qualities of this work from northwestern India suggest connections with the Greco-Roman styles of Gandhara, in present-day Pakistan."}},{"museum_id":"cleveland","language":"en","id":"cma-1970-156","position":167,"title":"Green Tara","category":"Indian and Southeast Asian Art","subtitle":null,"artist":"Aniko (Nepalese, active in Tibet mid- to late 1200s)","facts":[{"label":"Date","value":"c. 1260s, mounted 2020"},{"label":"Medium","value":"thangka; gum tempera, ink, and gold on sized cotton; mount: silk"},{"label":"Accession","value":"1970.156"}],"object_url":"https://clevelandart.org/art/1970.156","image":{"src":"/images/cleveland/cma-1970-156.jpg","sourceUrl":"https://clevelandart.org/art/1970.156","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"For Tibetans, Green Tara is one of the preeminent figures of their Buddhist faith, a radiant savioress who embodies the female form of the perfect, enlightened mind. The Green Tara in the Cleveland thangka—a Tibetan devotional painting on cloth—specifically dispels fear and provides protection, just like her mantra inscribed on the back side of the painting. Her green color and fear-not gesture link her to the cosmic Buddha of the North, enshrined above her head. Most scholars agree that this work was painted by the celebrated Nepalese artist known as Aniko."}},{"museum_id":"cleveland","language":"en","id":"cma-1973-15","position":168,"title":"Buddha","category":"Indian and Southeast Asian Art","subtitle":null,"artist":null,"facts":[{"label":"Date","value":"600s"},{"label":"Medium","value":"sandstone"},{"label":"Culture","value":"Thailand, probably Shri Thep, Mon-Dvaravati style"},{"label":"Accession","value":"1973.15"}],"object_url":"https://clevelandart.org/art/1973.15","image":{"src":"/images/cleveland/cma-1973-15.jpg","sourceUrl":"https://clevelandart.org/art/1973.15","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"This elegant, monumental sculpture is the earliest type of Buddha image to be made in Southeast Asia. It comes from a site in north-central Thailand that was part of the Dvaravati kingdom (500s–1200s). The body shows direct links with the sculptural traditions at Sarnath in northern India on the banks of the Ganges River. The expression of the face has the peaceful introspection that became canonical during the Gupta period of the 5th century in India. The shape of the head and facial features—unlike Indian precursors—suggest that the artists and patrons of Dvaravati made the Buddha resemble the local Mon population. The figure's stance has been rendered with remarkable fluidity, and the abstracted caps of the knees and minimalist modeling of the pelvis lend the figure an otherworldly, transcendent demeanor, balanced by the approachable smiling countenance."}},{"museum_id":"cleveland","language":"en","id":"cma-1918-549","position":169,"title":"Bridal Robe (Hwarot)","category":"Textiles","subtitle":null,"artist":null,"facts":[{"label":"Date","value":"1850–1910"},{"label":"Medium","value":"Satin weave silk; silk embroidery; paper edging on neck and sleeves"},{"label":"Culture","value":"Korea, Joseon dynasty (1392–1910)"},{"label":"Accession","value":"1918.549"}],"object_url":"https://clevelandart.org/art/1918.549","image":{"src":"/images/cleveland/cma-1918-549.jpg","sourceUrl":"https://clevelandart.org/art/1918.549","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"This bride's robe is exquisitely embroidered with various symbols of happiness in colorful silk threads. Butterflies stand for marital happiness; the phoenix, numerous offspring; and lotus flowers and white cranes, longevity. Yet, the bridal robe does not attest to the life of luxury. To the contrary, many traces of repairs, trimmings, and patchwork reflect Joseon period women’s commitment to value neo-Confucian aesthetics of frugality and modesty. Substantial repairs and patching reveal that this robe served as an important communal resource to be shared and passed down through several generations. Its collar and sleeves are covered in thick white paper; this paper is replaced with new paper for each bride, while the robe itself was reused for decades."}},{"museum_id":"cleveland","language":"en","id":"cma-1926-533","position":170,"title":"Royal Carpet with Silk and Metal Thread","category":"Textiles","subtitle":null,"artist":null,"facts":[{"label":"Date","value":"1600–1625"},{"label":"Medium","value":"Cotton: warp; cotton and silk: wefts; silk: pile, asymmetrical knot; gilt- and silver-metal thread: brocaded"},{"label":"Culture","value":"Iran, Isfahan, Safavid period (1501-1722)"},{"label":"Accession","value":"1926.533"}],"object_url":"https://clevelandart.org/art/1926.533","image":{"src":"/images/cleveland/cma-1926-533.jpg","sourceUrl":"https://clevelandart.org/art/1926.533","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"The Safavid dynasty was the greatest dynasty from Iran in the Islamic period. Similarly, woven textiles and carpets from this period are some of the best produced in the region. Royal workshops produced luxurious textiles, like this one, to furnish the royal court. Expertly woven silks were highly prized by the Iranian elite but were also produced for export to the European aristocracy."}},{"museum_id":"cleveland","language":"en","id":"cma-1940-530","position":171,"title":"Cloth with Procession of Figures","category":"Textiles","subtitle":null,"artist":null,"facts":[{"label":"Date","value":"170 BCE–70 CE (radiocarbon date, 95% probability)"},{"label":"Medium","value":"cotton and pigment (field); camelid fiber (borders and fringe)"},{"label":"Culture","value":"Central Andes, South Coast, Nasca people"},{"label":"Accession","value":"1940.530"}],"object_url":"https://clevelandart.org/art/1940.530","image":{"src":"/images/cleveland/cma-1940-530.jpg","sourceUrl":"https://clevelandart.org/art/1940.530","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"Experts agree that this cloth is one of the greatest paintings to survive from Andean antiquity due to the realism, complexity, large size, and refined execution of its figures. All but one of the figures wear the whiskered mouth mask of Nasca supernatural beings and several carry or wear severed human heads, which the Nasca linked to nature’s fruitfulness. Thus, the figures seem to represent supernatural forces or humans personifying such forces during a ritual devoted to agricultural fertility. Originally, the panel was attached along its upper edge to a dark blue cloth of equal size. The complete textile may have served as a mantle (a shawl-like garment), a hanging, or a funerary offering."}},{"museum_id":"cleveland","language":"en","id":"cma-1967-144","position":172,"title":"Icon of the Virgin and Child","category":"Textiles","subtitle":null,"artist":null,"facts":[{"label":"Date","value":"500s CE"},{"label":"Medium","value":"wool and dye"},{"label":"Culture","value":"Egypt, Byzantine period"},{"label":"Accession","value":"1967.144"}],"object_url":"https://clevelandart.org/art/1967.144","image":{"src":"/images/cleveland/cma-1967-144.jpg","sourceUrl":"https://clevelandart.org/art/1967.144","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"Woven from more than 20 colors of woolen thread, this rare tapestry was more expensive than a painting when it was made. The historical price reflected contemporary viewers’ appreciation for the skilled color blending by the weavers. Hung on a wall, this tapestry allowed viewers to venerate (honor) the Virgin Mary and the Christ Child in the Christian Orthodox church. Angels and apostles surround them, their names written in Greek. To be spiritually effective, an icon (devotional image) should follow its subject’s established visual tradition as closely as possible."}},{"museum_id":"cleveland","language":"en","id":"cma-1943-658","position":173,"title":"Bahram Gur Arrives at the House of a Merchant, text page (recto); Bahram Gur Slays a Dragon (verso), from a Shahnama (Book of Kings) of Firdausi (940–1019 or 1025), known as the Great Mongol Shahnama","category":"Islamic Art","subtitle":null,"artist":null,"facts":[{"label":"Date","value":"1330–35"},{"label":"Medium","value":"opaque watercolor, ink, and gold on paper"},{"label":"Culture","value":"Iran, Tabriz, Ilkhanid period (1256-1353)"},{"label":"Accession","value":"1943.658"}],"object_url":"https://clevelandart.org/art/1943.658","image":{"src":"/images/cleveland/cma-1943-658.jpg","sourceUrl":"https://clevelandart.org/art/1943.658","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"In this intense painting, Bahram Gur plunges his sword into the breast of a dragon. A favorite character from Iran's pre-Islamic history, Bahram Gur (reigned 420–38 CE) was a popular ruler of the Sasanian dynasty and a great hunter. He took the name \"Gur,\" meaning onager (a wild ass), because it was his preferred game, although he also excelled at killing dragons. As evidenced by this illustration's rock formations, tree trunk, and dragon, Iranian painting in the Mongol period borrowed numerous stylistic and spatial elements from Chinese models. With the surging landscape and writhing dragon rendered with equal energy, this is a picture of extraordinary unity and concentration."}},{"museum_id":"cleveland","language":"en","id":"cma-1944-485","position":174,"title":"The Wade Cup with Animated Script","category":"Islamic Art","subtitle":null,"artist":null,"facts":[{"label":"Date","value":"1200–1221"},{"label":"Medium","value":"brass inlaid with silver"},{"label":"Culture","value":"Iran, Seljuq period of Iran (1037–1194)"},{"label":"Accession","value":"1944.485"}],"object_url":"https://clevelandart.org/art/1944.485","image":{"src":"/images/cleveland/cma-1944-485.jpg","sourceUrl":"https://clevelandart.org/art/1944.485","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"The highlight of the cup’s decoration is the inscription around the rim, which you see on the walls around you, with letters composed of human figures, animals, and birds. This is known as animated script and it developed in northeast Iran or Afghanistan during the mid-1100s and migrated westward. The inscription on the rim of the Wade Cup is the pinnacle of this form of script with its full-figure animation. The body of the cup is covered with interlacing bands of compartments containing tiny figures of humans and animals. These represent the 12 signs of the zodiac from astrology, the practice of interpreting the influence of planets and stars on earthly affairs. Astrology began in Mesopotamia, was adopted by the Greeks, and then absorbed into medieval Islamic culture through translations of Greek texts."}},{"museum_id":"cleveland","language":"en","id":"cma-1944-492","position":175,"title":"Dragon in foliage with lion and phoenix heads","category":"Islamic Art","subtitle":null,"artist":"Sahkulu (Turkish, active 1526–56)","facts":[{"label":"Date","value":"mid-1500s"},{"label":"Medium","value":"Ink, gum tempera, and gold on paper"},{"label":"Accession","value":"1944.492"}],"object_url":"https://clevelandart.org/art/1944.492","image":{"src":"/images/cleveland/cma-1944-492.jpg","sourceUrl":"https://clevelandart.org/art/1944.492","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"A dragon lunges toward a pearl in the form of a seal inscribed with a verse from the Koran: “And I commit my case unto God” (40:44). In his front claw, the dragon grasps two flowering branches that magically produce a variety of blooms, including a lion that bites the dragon’s neck and a phoenix, who competes for the pearl. Sahkulu was trained by Persian artists, as were many artists of Mughal India during the 1500s. He joined the Ottoman imperial painting atelier in Istanbul in 1526 and became the head in 1545."}},{"museum_id":"cleveland","language":"en","id":"cma-1985-144","position":176,"title":"Trophy of the Hunt","category":"Photography","subtitle":null,"artist":"Adolphe Braun (French, 1812–1877)","facts":[{"label":"Date","value":"c. 1867"},{"label":"Medium","value":"carbon print"},{"label":"Accession","value":"1985.144"}],"object_url":"https://clevelandart.org/art/1985.144","image":{"src":"/images/cleveland/cma-1985-144.jpg","sourceUrl":"https://clevelandart.org/art/1985.144","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"Braun intended his extraordinarily large prints as affordable middle-class alternatives to the painted hunt scenes adorning the country houses of the European upper classes. Here he shows an array of game birds prized for their flavor and the hunting challenge they offer. The 19th-century versions, created by photographers and even some Impressionist painters, evoke a leisurely rural pastime that was becoming rare in an increasingly urban, industrialized France."}},{"museum_id":"cleveland","language":"en","id":"cma-2002-45","position":177,"title":"Sand Dunes, Carson Desert, Nevada","category":"Photography","subtitle":null,"artist":"Timothy H. O'Sullivan (American, 1840–1882)","facts":[{"label":"Date","value":"1867"},{"label":"Medium","value":"albumen print from wet collodion negative"},{"label":"Accession","value":"2002.45"}],"object_url":"https://clevelandart.org/art/2002.45","image":{"src":"/images/cleveland/cma-2002-45.jpg","sourceUrl":"https://clevelandart.org/art/2002.45","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"This noontime scene conveys a desolate place discovered by a lonely explorer. The artist chose a vantage point and framing that blocked the horizon and showed a single wagon—the former Civil War ambulance that he converted into a portable darkroom—and only two sets of footprints. However, over the previous 25 years, more than 165,000 people had passed near here on their way to California."}},{"museum_id":"cleveland","language":"en","id":"cma-2006-4","position":178,"title":"Winter Trees Reflected in a Pond","category":"Photography","subtitle":null,"artist":"William Henry Fox Talbot (British, 1800–1877)","facts":[{"label":"Date","value":"1841–42"},{"label":"Medium","value":"salted paper print from calotype negative"},{"label":"Accession","value":"2006.4"}],"object_url":"https://clevelandart.org/art/2006.4","image":{"src":"/images/cleveland/cma-2006-4.jpg","sourceUrl":"https://clevelandart.org/art/2006.4","license":"CC0","sourceLabel":"Cleveland Museum of Art"},"guide":{"text":"Talbot captured tree branches flawlessly mirrored on the glassy surface of the pond at his family seat, the 13th-century Lacock Abbey in Wiltshire. A longer exposure, or a lusher season, would have risked a blurred image. The result was a radically abstract composition for its time—a starkly beautiful landscape, as expressive and personal as any painting."}}]$seed$::jsonb)
on conflict (museum_id, language, id) do update set
  position = excluded.position, title = excluded.title, category = excluded.category,
  subtitle = excluded.subtitle, artist = excluded.artist, facts = excluded.facts,
  object_url = excluded.object_url, image = excluded.image, guide = excluded.guide;
